INSERT INTO quest_set (id, title, description, sandbox_type, category) VALUES
  (1,  '리눅스 기초 1 — 파일 탐색과 생성', '현재 위치 확인, 디렉토리 이동, 파일/디렉토리 생성과 복사를 실습합니다.', 'linux',             '리눅스'),
  (2,  '리눅스 기초 2 — 삭제·검색·권한',  '파일 삭제, 내용 확인, 문자열 검색, 권한 변경, 링크 생성을 실습합니다.',  'linux',             '리눅스'),
  (3,  '리눅스 기초 3 — 프로세스와 시스템', '프로세스 확인/종료, 디스크/메모리 확인, 환경변수 설정을 실습합니다.', 'linux',             '리눅스'),
  (4,  '리눅스 네트워크/파일 전송',         'curl, ping, scp, rsync 등 네트워크 확인과 서버 간 파일 전송을 실습합니다.', 'linux-ssh',      '리눅스'),
  (5,  'Docker 기초',                       '컨테이너 실행·중지·삭제, 이미지 관리, 로그 확인 등 Docker 기본 조작을 실습합니다.', 'docker',    '도커'),
  (6,  'k8s 기초',                          'kubectl로 Pod, Deployment, Service를 직접 조작해봅니다.', 'k8s',                           'k8s'),
  (7,  '리눅스 압축과 아카이브',            'tar, gzip, zip 등 압축/아카이브 명령어를 실습합니다. 오프라인 패키지 반입의 기초입니다.', 'linux', '리눅스'),
  (8,  'Docker 이미지 오프라인 반입',       'tar 파일로 이미지를 save/load하고 로컬 레지스트리에 push하는 현장 패턴을 실습합니다.', 'docker-persistent', '도커'),
  (9,  'Vim 기초',                          '현장에서 가장 자주 막히는 Vim 편집 패턴을 실습합니다. 열고 저장하는 것부터 설정 파일 수정까지.', 'linux', '리눅스'),
  (10, '리눅스 현장 운영',                  'systemd, rpm, 환경변수, 방화벽 등 실제 서버 운영에서 반드시 쓰는 명령어를 실습합니다.', 'linux-systemd', '리눅스'),
  (11, 'Docker 이미지 빌드',               'Dockerfile 작성부터 이미지 빌드, 태깅까지 이미지를 직접 만드는 과정을 실습합니다.', 'docker', '도커'),
  (12, 'k8s ConfigMap과 Secret',           'ConfigMap과 Secret을 생성하고 Pod에 환경변수와 볼륨으로 주입하는 패턴을 실습합니다.', 'k8s', 'k8s'),
  (13, 'k8s 스토리지와 네트워크',          'PersistentVolume/PVC로 데이터를 영속 저장하고 port-forward로 클러스터 내부 서비스에 접근하는 패턴을 실습합니다.', 'k8s', 'k8s'),
  (14, 'Helm 기초',                         'Helm으로 차트를 설치하고 값을 커스터마이징하는 현장 패턴을 실습합니다. repo 추가부터 업그레이드·롤백까지.', 'k8s', 'k8s'),
  (15, '리눅스 로그와 텍스트 처리',       '로그에서 필요한 줄과 숫자를 뽑아내는 현장 패턴을 실습합니다. grep, 리다이렉션, sort/uniq, awk, sed.', 'linux', '리눅스'),
  (16, '리눅스 장애 진단 실전',          '디스크 부족, 과다 CPU, 포트 충돌, 권한 오류 등 장애 상황에서 원인을 찾고 해결하는 패턴을 실습합니다.', 'linux', '리눅스'),
  (17, '리눅스 쉘 스크립트 기초', '변수와 인자, 조건문, 반복문, 종료 코드로 현장에서 쓰는 작은 쉘 스크립트를 직접 작성합니다.', 'linux', '리눅스'),
  (18, '리눅스 네트워크 진단', 'curl, nc, ss, /etc/hosts 로 서비스가 응답하는지, 포트가 열려 있는지, 이름이 풀리는지 확인하는 현장 패턴을 실습합니다.', 'linux', '리눅스'),
  (19, 'kubectl 속도와 실전', 'dry-run으로 YAML 뼈대 만들기, 명령형 수정, jsonpath, custom-columns, explain, patch 등 시간 제한 실기(CKA 등)에서 점수를 가르는 kubectl 손기술을 실습합니다.', 'k8s', 'k8s'),
  (20, 'k8s 일상 운영 기본기', '노드·IP 확인, exec, 로그, 이벤트, 라벨 셀렉터, 롤아웃 이력·재시작, YAML 백업 등 매일 쓰는 kubectl 기본 명령을 실습합니다.', 'k8s', 'k8s'),
  (21, '리눅스 쉘 기본기와 사용자·권한', '와일드카드, 인용부호, xargs, tee, diff, alias, 사용자·그룹, su, umask, 하드링크 등 매일 쓰는 쉘 기본기를 실습합니다.', 'linux', '리눅스'),
  (22, 'k8s 워크로드 기본', 'Job·CronJob, DaemonSet, requests/limits, 프로브, nodeSelector, initContainers, HPA 등 워크로드의 기본 구성 요소를 실습합니다.', 'k8s', 'k8s'),
  (23, 'k8s 트러블슈팅 실전', '깨진 워크로드의 원인을 describe·logs·events 로 찾아 직접 고칩니다. 이미지 오타, 셀렉터·포트 불일치, CrashLoopBackOff, Pending, 설정 참조 오류 등.', 'k8s', 'k8s'),
  (24, '리눅스 패키지와 systemd 로그', 'rpm 으로 패키지를 조회·검증하고, journalctl·logger 로 로그를 찾고, systemd 유닛을 만들어 시작하고 실패 원인을 찾는 현장 패턴을 실습합니다.', 'linux-systemd', '리눅스'),
  (25, 'k8s 서비스와 네트워킹', 'Service 유형, 엔드포인트, 클러스터 DNS, Ingress, NetworkPolicy, Headless Service 등 k8s 네트워킹의 기본 구성을 실습합니다.', 'k8s', 'k8s'),
  (26, 'k8s 스케줄링과 배포 전략', 'taint·toleration, nodeAffinity, podAntiAffinity, 롤링 업데이트 전략, StatefulSet, PodDisruptionBudget, graceful shutdown, kubectl diff 등 Pod 배치와 배포 방식을 다루는 기본기를 실습합니다.', 'k8s', 'k8s'),
  (27, '리눅스 성능과 스토리지(NFS) 점검', '메모리·CPU·로드를 점검하고 df 계열 출력을 읽으며, NFS 마운트 설정(fstab, exports)과 출력을 해석하는 현장 점검 패턴을 실습합니다.', 'linux', '리눅스'),
  (28, '리눅스 명령어 확인 퀴즈', '명령어의 옵션 의미, 권한과 출력 읽기, 용량·메모리 해석, 종료 코드, NFS 장애 해석까지 객관식으로 확인합니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'quiz', '리눅스'),
  (29, 'k8s CKA 개념·명령 퀴즈', 'Pod/Deployment/Service, 장애 상태(CrashLoopBackOff, Pending, OOMKilled), 프로브, 롤백, Secret, kubectl 사용법을 CKA 연습처럼 객관식으로 확인합니다.', 'quiz', 'k8s'),
  (30, '리눅스 터미널로 확인하고 고르기', '터미널에서 직접 명령을 실행해 로그, 디렉터리 용량, 권한, 종료 코드, 설정 파일을 확인하고 그 결과로 정답을 고르는 실습형 객관식입니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'linux', '리눅스'),
  (31, 'k8s 터미널로 확인하고 고르기', 'kubectl 로 Pod 의 실패 원인, Pending 이유, 배포 이력, Service 연결, ConfigMap·Secret 값, 라벨, 컨테이너 환경변수를 직접 확인하고 그 결과로 정답을 고르는 실습형 객관식입니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'k8s', 'k8s'),
  (32, '리눅스 증상의 원인을 원리로 풀기', '"안에서는 되는데 밖에서만 안 된다", "지웠는데 용량이 그대로다" 같은 현장 증상을 터미널에서 직접 재현하고, 그 **원리**(루프백 바인딩, 종료 코드와 시그널, UID 권한, 열린 파일, 이름 해석 순서, inode, 좀비 프로세스)를 객관식으로 확인합니다. 해설에서 왜 그런지와 오답이 틀린 이유를 함께 봅니다.', 'linux', '리눅스'),
  (33, 'k8s 쉬운 장애 고치기', '이미지 태그·주소 오류 고치기, ConfigMap 변경 후 재시작, Pod 개수 늘리기, 없는 StorageClass 때문에 Pending 인 PVC 고치기, 실패한 배포 되돌리기, 컨테이너 2개짜리 Pod 와 kubectl 정렬 옵션까지 현장에서 가장 자주 만나는 쉬운 장애와 기본 작업을 직접 고칩니다.', 'k8s', 'k8s'),
  (34, '리눅스 명령 연결하기: 파이프와 리다이렉션', '파이프(|)로 명령의 결과를 다른 명령에 넘기고, >, >>, <, 2> 로 입출력을 파일에 연결하고, &&, ||, ; 로 명령을 이어 실행하는 법을 연습합니다. grep, awk, sort 같은 도구를 조합하기 전에 꼭 필요한 연결 문법입니다.', 'linux', '리눅스'),
  (35, '리눅스 반복 작업 한 줄로 끝내기', '같은 일을 여러 번 해야 할 때 for 와 while read 로 한 줄에 끝내는 법을 연습합니다. 파일 여러 개 처리, 숫자 범위 반복, 확장자 일괄 변경, 서버 목록 순회, 조건으로 골라 처리하기, 반복 멈추기, 그리고 반복문이 이름의 공백에서 깨지는 이유를 다룹니다.', 'linux', '리눅스'),
  (36, '리눅스 이름으로 통신하기', '서버끼리 이름으로 통신하게 만드는 /etc/hosts 사용법(여러 서버 등록, 별칭, 옛 IP 고치기, 백업과 복구)과, 이름으로 포트에 접속되는지 확인하는 법을 연습합니다. 접속 오류 메시지가 어느 단계(이름 해석, 포트, 서비스)의 문제인지 읽고 확인 순서를 익힙니다.', 'linux', '리눅스'),
  (37, 'k8s 통신 방법 익히기', 'Pod 끼리 IP 로 통신하기와 그 한계(IP 가 바뀜), 같은 Pod 안의 localhost 통신, 임시 Pod 로 Service 통신 테스트하기, 짧은 이름이 되는 이유(resolv.conf 의 search), Service 의 port 와 targetPort, 외부 접속 방법의 선택 기준을 직접 해 보며 익힙니다.', 'k8s', 'k8s'),
  (38, 'Dockerfile 읽고 이해하기', 'Dockerfile 의 각 줄이 무슨 일을 하는지 읽고, 줄 순서와 명령을 직접 맞춰 보며 Dockerfile 을 읽는 눈을 기릅니다. 줄 순서 맞추기, 빈칸 채우기, 객관식으로 터미널 없이 풀어요.', 'quiz', '도커'),
  (39, 'docker compose 파일 읽고 이해하기', '여러 컨테이너를 한 파일로 정의하는 compose.yaml 을 읽고, 포트·의존성·볼륨·서비스 이름 통신이 무슨 뜻인지 직접 맞춰 봅니다. 빈칸 채우기, 순서 맞추기, 객관식으로 터미널 없이 풀어요.', 'quiz', '도커'),
  (42, '리눅스 기초 개념 먼저 이해하기', '파일 경로, 권한, 프로세스처럼 리눅스 실습의 바탕이 되는 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', '리눅스'),
  (40, 'Docker 개념 먼저 이해하기', '이미지와 컨테이너, 레지스트리, 포트 연결, 볼륨 같은 Docker 의 기본 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', '도커'),
  (41, 'k8s 개념 먼저 이해하기', 'Pod, Deployment, Service, Namespace, ConfigMap 과 Secret 같은 쿠버네티스의 기본 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', 'k8s'),
  (43, '명령 연결 개념 먼저 이해하기: 출력·오류·파이프', '명령의 정상 출력과 오류가 어디로 나가는지, `>`·`>>`·`2>&1`·파이프(`|`)·`&&`·`||` 가 무엇을 하는지 터미널 없이 먼저 이해합니다. 이 개념은 뒤의 프로세스·로그·find 실습에서 계속 쓰입니다.', 'quiz', '리눅스'),
  (44, 'find 천천히 익히기: 찾고, 걸러내고, 실행하기', '파일을 찾는 `find` 를 옵션 하나씩 익힙니다. 구조 이해부터 이름·종류·크기·시간·깊이 조건, 조건 조합(`-o`, `!`), 찾은 파일에 명령 실행(`-exec`), 삭제(`-delete`), `xargs` 연결, 여러 조건을 한꺼번에 만족하는 종합 문제까지 단계별로 연습합니다.', 'linux', '리눅스'),
  (45, '명령어 해부하기: 복사하기 전에 읽는 법', '인터넷에서 복사한 명령을 무슨 뜻인지 모른 채 붙여 넣고 있진 않나요? 명령·옵션·인자를 나눠 읽는 법, 낯선 명령을 쓸 때의 안전한 순서, 위험한 명령을 알아보는 눈, 실행 결과를 미리 짐작하는 연습을 터미널 없이 합니다.', 'quiz', '리눅스'),
  (46, 'kubectl 명령과 YAML 해부하기', 'kubectl 명령이 어떤 구조로 이루어져 있는지, Deployment YAML 의 각 부분이 무슨 뜻인지, 라벨과 셀렉터가 어떻게 이어지는지를 클러스터 없이 읽고 맞춰 봅니다. 복사해서 붙이기 전에 읽는 힘을 기릅니다.', 'quiz', 'k8s'),
  (47, '도움말로 명령 완성하기: --help 읽고 직접 찾기', '옵션을 외우는 것이 아니라 **도움말에서 찾아 쓰는 법**을 익힙니다. 정답 옵션은 알려 주지 않습니다. `명령 --help` 를 읽고, `| grep` 으로 필요한 줄만 골라 보며 명령을 스스로 완성해 보세요.', 'linux', '리눅스'),
  (48, 'grep 천천히 익히기: 글자로 줄 찾기', '파일 **안의 글자**를 찾는 `grep` 을 옵션 하나씩 익힙니다. `find`(이름·속성을 찾는 명령)와의 차이, 대소문자(`-i`), 제외(`-v`), 줄 번호(`-n`), 개수(`-c`), 단어(`-w`), 폴더 전체(`-r`, `-l`), 또는(`-E`), 일부만 뽑기(`-o`), 앞뒤 줄(`-A`/`-B`)을 연습하고 마지막에 합쳐서 씁니다. 옵션은 `--help` 에서 찾는 방법도 함께 안내합니다.', 'linux', '리눅스'),
  (49, '텍스트 도구 입문: 센다, 정렬한다, 뽑는다', '`wc`, `head`/`tail`, `sort`, `uniq`, `cut`, `tr` 을 하나씩 익히고 `|` 로 이어 "가장 많이 나온 것 찾기" 같은 일을 한 줄로 해 봅니다. 로그와 목록을 다루는 모든 작업의 기본 도구입니다.', 'linux', '리눅스'),
  (50, '따옴표·변수·치환 익히기: 쉘이 먼저 해석하는 것들', '명령은 실행되기 **전에** 쉘이 먼저 해석합니다. 작은따옴표와 큰따옴표의 차이, 변수 지정과 `$변수`, 명령 치환 `$( )`, 공백이 든 이름, `$` 를 글자 그대로 쓰기, `export` 를 연습합니다. 복사한 명령이 왜 그렇게 쓰였는지 읽는 힘이 생깁니다.', 'linux', '리눅스'),
  (52, 'Git 기초: 저장소 만들고 기록하기', 'CI/CD 의 출발점인 Git 을 터미널에서 직접 익힙니다. 사용자 설정, 저장소 만들기, 상태 확인(`status`), 기록(`add`·`commit`), 변경 확인(`diff`), 이력 보기(`log`), 일부만 커밋, `.gitignore` 까지 한 걸음씩 연습합니다.', 'linux', 'Git'),
  (51, 'HAProxy 로드밸런서 익히기: 나누고, 거르고, 확인하기', '요청을 여러 서버로 나눠 주는 HAProxy 를 직접 다뤄 봅니다. frontend·backend 구조, 문법 검사(`haproxy -c`), 서버 추가, 번갈아 분산(roundrobin), 경로별 라우팅(`use_backend`), 헬스체크, 통계 화면, 가중치를 하나씩 연습합니다.', 'linux', '미들웨어'),
  (53, 'Git 브랜치와 병합: 갈라지고 합치고 충돌 풀기', 'CI/CD 의 핵심인 브랜치 작업을 익힙니다. 브랜치 만들기와 이동(`switch`), 목록(`branch`), 병합(`merge`)의 두 종류(fast-forward, 병합 커밋), 충돌 읽고 해결하기, 합친 브랜치 정리, 긴급 수정 흐름 종합까지 연습합니다.', 'linux', 'Git'),
  (54, 'Git 원격과 협업: 복제하고 올리고 받아오기', '혼자 쓰던 Git 을 팀 작업으로 넓힙니다. 로컬과 원격의 차이, 복제(`clone`), 원격 확인(`remote -v`), 올리기(`push`, `push -u`), 받아오기(`pull`), 안전하게 확인(`fetch`), 거절된 push 풀기, 브랜치로 작업해 올리는 흐름까지 연습합니다. 원격은 샌드박스 안의 로컬 저장소로 대신합니다.', 'linux', 'Git'),
  (55, '인프라 용어 지도: RHV·RHOV·OSP·OCP 헷갈리지 않기', '레드햇·VMware 계열의 비슷해 보이는 이름들(RHV, RHOV, RHOSP/OSP, RHOSO, OCP, vSphere/vCenter, KVM, KubeVirt)을 "VM 을 관리하나, 컨테이너를 관리하나" 라는 축으로 구분합니다. 이름이 나왔을 때 어느 층의 이야기인지 바로 떠올리는 것이 목표입니다.', 'quiz', '인프라'),
  (56, 'Git 되돌리기와 복구: 실수해도 되돌릴 수 있다', '현장에서 가장 두려운 순간, "실수했다"에 대처하는 법입니다. 수정 버리기(`restore`), 스테이징 취소, 커밋 고치기(`amend`), 합치기(`reset --soft`), 이력을 지우지 않는 되돌리기(`revert`), 임시 보관(`stash`), 날린 커밋 되살리기(`reflog`), 엉뚱한 push 를 막는 `--no-track`, `cherry-pick` 을 연습합니다. 실제 현장 복구 사례를 바탕으로 했습니다.', 'linux', 'Git'),
  (57, '관측 입문: 메트릭·로그·트레이스와 도구 구분', '모니터링과 관측 가능성의 차이, 세 가지 신호(Trace·Metric·Log), Prometheus 의 pull 수집과 저장 구조, Thanos·ServiceMonitor, Loki 의 레이블 인덱싱, Promtail·Alloy·Logstash·Vector 의 구분을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (58, 'Kafka 와 CDC: 토픽·파티션부터 Debezium 흐름까지', 'Kafka 의 토픽·파티션·offset, 컨슈머 그룹, 복제(Leader/Follower), 멱등 프로듀서, DLQ 와 RabbitMQ 와의 차이를 정리하고, CDC 의 개념과 binlog, Debezium 으로 변경이 Kafka 까지 흘러가는 순서와 필요한 권한을 문제로 익힙니다.', 'quiz', '미들웨어'),
  (59, 'MariaDB 복제·Galera·복구: 무엇이 어긋났는지 읽기', 'MariaDB 의 Primary-Replica 복제와 Galera Cluster(동기 복제, Certification 충돌 처리, AUTO_INCREMENT, recv_queue), failover 와 split-brain, MaxScale 구성 요소, PITR, 그리고 실제 복제 장애 복구 절차(상태 확인, 임시 skip 의 위험, dump 옵션, GTID 재연결)를 문제로 정리합니다.', 'quiz', '데이터베이스'),
  (60, 'Redis 익히기: 자료구조와 만료, 카운터, 분산 락', '메모리 기반 key-value 저장소 Redis 를 `redis-cli` 로 직접 다뤄 봅니다. 값 저장과 만료(TTL), 원자적 카운터(INCR), 해시·리스트·집합·정렬된 집합 자료구조, 그리고 `SET NX EX` 로 분산 락을 잡는 기본을 연습합니다.', 'linux', '데이터베이스'),
  (61, '인프라 스토리지·네트워크: Ceph, Cinder, Neutron 구분하기', '"저장소는 하나, 연결 계층이 둘" 이라는 구도로 Ceph·ODF·Cinder 를, "엔진 하나, 연결 계층 둘" 이라는 구도로 OVN·Neutron·OVN-Kubernetes 를 구분합니다. OpenStack 의 VM 프로비저닝 흐름, 테넌트, Proxmox 와의 규모 차이도 문제로 정리합니다.', 'quiz', '인프라'),
  (62, 'Elasticsearch 입문: 역색인, 샤드, refresh 와 flush', 'Elasticsearch 의 역색인, 샤드(Primary·Replica)와 클러스터 상태 색깔, 노드 역할, 색인된 문서가 저장되는 흐름(Translog, refresh, flush), Segment 불변성, 매핑(text·keyword), query 와 filter 의 차이를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (63, 'HAProxy 심화: 분산 방식, 연결 제한, TLS, 이중화', 'HAProxy 의 분산 알고리즘(leastconn, source), 세션 고정, 타임아웃과 maxconn·queue, SSL Termination 과 Passthrough, SNI, 그리고 VIP·Keepalived·VRRP 로 HAProxy 자체를 이중화하는 흐름, rate limiting, retry 와 redispatch 를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (64, 'CI/CD 도구 입문: Jenkins, Nexus, Harbor', 'CI 와 CD 의 구분, Jenkinsfile(pipeline·agent·stages·steps·post·when)과 controller·agent, Nexus 의 저장소 종류(hosted·proxy·group), Harbor 와 이미지 주소 읽기, 이미지를 올리고 받아 쓰는 순서, ImagePullBackOff 와 latest 태그의 위험을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (65, '권한과 소유자: chmod, chown, umask', '`ls -l` 의 권한 문자열 읽기, 숫자 권한(644, 755, 600)과 기호 권한(`+x`, `o-w`), `chmod` 와 `chown`·`chgrp`, 새 파일의 기본 권한을 정하는 `umask`, 그리고 777 이 위험한 이유를 연습합니다. 복사한 명령의 권한 부분을 이해하고 고칠 수 있게 됩니다.', 'linux', '리눅스'),
  (66, 'RabbitMQ 입문: Exchange·Queue·Binding과 안정적 전달', 'RabbitMQ(AMQP)의 Exchange·Queue·Binding·routing key 구조와 exchange 타입(direct, fanout, topic), ack 와 재전달, prefetch, 재시작에도 유지하는 durable·persistent, Dead Letter Exchange, 그리고 Kafka 와 어느 상황에 무엇을 쓰는지 문제로 정리합니다.', 'quiz', '미들웨어'),
  (68, 'CDC 운영 심화: 양방향 루프 방지, 초기 동기화, 장애 복구', '두 DB 를 서로 동기화하는 양방향 CDC 를 운영할 때 마주치는 문제를 문제로 정리합니다. 무한 루프를 막는 sql_log_bin=0, PK 대역 분리, 초기 동기화 순서, DELETE·tombstone 처리, 커넥터 재시작과 offset 무효화, at-least-once 와 멱등 sink, Galera 와 CDC 의 주의점을 다룹니다.', 'quiz', '미들웨어'),
  (69, '연쇄 장애 읽기: 증상 뒤의 원인 찾기', '운영에서 흔히 겪는 연쇄 장애를 바탕으로 한 사례로, 증상에서 원인으로 거슬러 올라가는 법을 익힙니다. Kafka CPU 폭증의 진짜 원인(NetworkPolicy 로 막힌 ES), 파이프라인 구간별 유실 여부, Galera 노드 복구와 쿼럼 상실, 비대칭 라우팅, 장애 테스트 전 기록을 다룹니다.', 'quiz', '미들웨어'),
  (70, 'HAProxy 와 Istio 함께 읽기: Gateway·VirtualService', 'HAProxy 가 앞단에서 L4 로 넘기고 Istio Gateway·VirtualService 가 TLS 종단과 도메인 라우팅을 맡는 구성을 읽습니다. 트래픽 흐름, 역할 차이, TLS 패스스루, 새 서비스 추가 절차, 리다이렉트와 경로 라우팅, NodePort 연결을 다룹니다.', 'quiz', '미들웨어'),
  (71, 'Elasticsearch ILM 운영: 인덱스의 일생과 저장소', '로그·메트릭이 계속 쌓이는 Elasticsearch 를 ILM 으로 관리하는 법을 익힙니다. hot/warm/cold/delete 단계, rollover, 정책과 템플릿의 차이, 인덱스 단위 삭제, 샤드·레플리카, 쿠버네티스의 StorageClass·PV·PVC 를 다룹니다.', 'quiz', '미들웨어'),
  (67, 'Kafka 운영 심화: 복제와 안전한 쓰기, 접속 주소, 순차 재시작', 'ISR 과 acks·min.insync.replicas 로 안전하게 쓰는 법, Controller 와 파티션 Leader 의 차이, KRaft 쿼럼을 순차로 재시작하는 이유, advertised.listeners 와 HAProxy 포트 매핑, 보관정책, Kafka Connect 내부 토픽, 멱등 전달을 운영 사례 중심으로 정리합니다.', 'quiz', '미들웨어'),
  (72, 'HAProxy 활용 케이스 실습: TCP 포워딩, 도메인 분기, 이중화', '실무에서 자주 쓰는 HAProxy 구성을 샌드박스에서 직접 만들어 봅니다. Kafka 처럼 HTTP 가 아닌 트래픽을 넘기는 TCP 포워딩(브로커별 포트), 도메인별 ACL 분기, 헬스체크 경로가 틀렸을 때 고치고 reload 하기, 리다이렉트, backup 서버로 이중화하기를 연습합니다.', 'linux', '미들웨어'),
  (73, '장애 복구 절차 읽기: Galera 와 Kafka', 'Galera 노드 장애와 Kafka 브로커 장애를 복구하는 절차를 읽고 순서와 이유를 익힙니다. 단일 노드 복구 순서, 로그에서 볼 오류 패턴, SST 와 IST, 쿼럼 복구 뒤 노드를 하나씩 올리는 이유, ISR 확인, 강제 리더 선출(unclean)의 위험, 메타데이터 손상 시 백업 우선, 오프셋 초기화를 다룹니다.', 'quiz', '미들웨어'),
  (74, '메트릭 파이프라인 읽기: Prometheus → Vector → Kafka', '클러스터 내부 Prometheus 에서 federate 로 메트릭을 가져와 recording rule 로 가공하고 Vector 로 변환·집계해 Kafka 로 보내는 메트릭 파이프라인을 읽습니다. federation 과 remote_write, recording rule, Vector 의 변환 단계와 reduce, 토픽 분리, HAProxy 를 거치는 federate 통신, 토큰 권한 오류와 단계별 진단을 다룹니다.', 'quiz', '미들웨어'),
  (75, '리눅스 운영 기본기: SSH 키, 시간 동기화, NFS, 정책 라우팅', '현장 서버를 다룰 때 매일 쓰는 운영 기본기를 익힙니다. SSH 공개키/개인키 인증(키 생성, authorized_keys 등록, 권한), 클러스터에서 시간 동기화(chrony)가 중요한 이유, NFS 임시 마운트와 언마운트가 안 될 때, 비대칭 라우팅과 정책 라우팅의 임시·영구 적용을 다룹니다.', 'linux', '리눅스'),
  (76, 'Elasticsearch 심화: 검색 점수, 분석기, 샤드 운영', '검색 결과의 순서를 정하는 BM25 와 분석기(Analyzer)의 3단계, 세그먼트를 합치는 merge, 준실시간 검색과 refresh, 샤드 할당·재분배와 노드를 순차 재시작할 때의 설정, 미할당 샤드의 원인을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (77, '컨테이너의 정체: 격리된 프로세스, 네임스페이스와 cgroup, 이미지 레이어', '컨테이너는 가상 컴퓨터가 아니라 **격리된 프로세스**입니다. 네임스페이스(무엇을 보는가)와 cgroup(얼마나 쓰는가), 이미지 레이어와 쓰기 시 복사(CoW), OCI·CRI·containerd, 레지스트리와 태그를 개념으로 잡고, 샌드박스 안에서 네임스페이스·PID 1·cgroup 을 직접 읽어 확인합니다.', 'linux', '도커'),
  (78, 'k8s 구조 이해하기: 컨트롤 플레인, 노드, 선언형 모델', 'kubectl 로 명령을 내리기 전에 쿠버네티스가 안에서 어떻게 움직이는지 큰 그림을 잡습니다. 컨트롤 플레인(API Server, etcd, Scheduler, Controller), 노드의 kubelet·컨테이너 런타임·kube-proxy, 선언형 모델과 reconcile, CRD 와 Operator 를 문제로 정리합니다.', 'quiz', 'k8s'),
  (79, 'k8s 스케줄링 운영 개념: Taint, drain, DaemonSet, Ingress', '노드를 점검하거나 워크로드를 배치할 때 쓰는 개념을 문제로 정리합니다. Taint 와 Toleration, Affinity 와의 방향 차이, cordon·drain·eviction 과 PodDisruptionBudget, Pod·Sidecar·DaemonSet 의 구분, Ingress·Egress 의 방향과 Gateway API 를 다룹니다.', 'quiz', 'k8s'),
  (80, 'k8s 네트워크와 외부 노출: CNI, Service, NodePort, NFS', 'Pod 가 서로, 그리고 밖과 어떻게 통신하는지 구조를 잡습니다. CNI 와 같은 노드·다른 노드 통신, Flannel 과 Calico 의 차이, NetworkPolicy, Service 가 iptables 로 L4 로드밸런싱하는 방식과 IPVS, ClusterIP·NodePort·LoadBalancer, port 와 targetPort, NFS 볼륨이 필요한 이유를 문제로 정리합니다.', 'quiz', 'k8s'),
  (81, 'DNS 와 이름 해석: 왜 깨지고 어떻게 확인하나', '"서버에 접속이 안 돼요"의 원인이 DNS 인 경우는 많습니다. DNS 가 깨지는 흔한 방식(ndots, 네거티브 캐싱, 시작 시 한 번만 resolve 하는 앱, TCP 53 차단), `/etc/hosts` 와 `dig` 결과가 달라지는 이유, UDP 의 특성, OSI 계층 용어를 개념으로 잡고, 이름 해석 순서와 `/etc/hosts` 를 샌드박스에서 직접 확인합니다.', 'linux', '리눅스'),
  (82, 'GitOps 와 k8s 위의 CI/CD: Argo CD, Jenkins Pod, 이미지 빌드', 'GitOps 와 Argo CD(Git 을 진실로 두고 클러스터가 당겨서 맞춘다), push 와 pull 배포의 차이, merge 가 배포이고 revert 가 롤백인 이유, 그리고 Jenkins·Gitea 같은 상태 있는 서비스를 Pod 로 운영할 때 달라지는 것(PVC, Recreate, agent Pod, daemon 없는 이미지 빌드, 설정의 코드화)과 IaC 도구(Pulumi)를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (83, 'Redis 심화: 원자성, 안전한 락 해제, 영속화와 메모리', 'Redis 가 명령 하나는 원자적이지만 여러 명령 사이에는 다른 클라이언트가 끼어들 수 있다는 점에서 출발해, MULTI/EXEC 와 Lua 스크립트의 차이, 남의 락을 지우지 않는 안전한 락 해제, 한도 안에서만 증가하는 카운터, TTL 해제(PERSIST), AOF 영속화와 메모리 한도(eviction) 설정을 실습합니다.', 'linux', '데이터베이스'),
  (84, 'HAProxy 운영 심화: 로그 읽기, 요청 제한, 차단, URI 분산', 'HAProxy 로그의 타이밍 필드로 병목을 읽고(Tw, Tc, Tr), 요청 로그를 직접 남기고, 경로 차단(403)과 요청 빈도 제한(429, stick-table), 연결 수 제한의 차이, URI 해시 분산(balance uri)을 실습합니다.', 'linux', '미들웨어'),
  (85, '프로세스와 파일시스템 이해하기: fork·exec, /proc, 커널 모드', '리눅스를 쓰는 모든 명령의 바탕이 되는 개념을 잡습니다. 프로세스를 만드는 fork 와 exec(PID 가 어떻게 변하나), 쓰기 시 복사(CoW), "모든 것은 파일이다"(/proc, /dev), 파일시스템 계층(/etc, /var, /tmp, /usr), 유저 모드와 커널 모드, 시스템 콜을 개념으로 익히고 샌드박스에서 직접 확인합니다.', 'linux', '리눅스'),
  (86, '분산 시스템 핵심 개념: 합의, 일관성, Saga, 멱등, 백프레셔', 'Kafka·etcd·데이터베이스를 이해하는 바탕이 되는 분산 시스템 개념을 정리합니다. 합의(Paxos·Raft)와 과반수(quorum), Raft 커밋과 Kafka acks 의 차이, 강한 일관성과 최종 일관성, 이벤트 기반 구조, 2PC 의 한계와 Saga(보상 트랜잭션), 멱등성, 백프레셔, 배치와 스트림 처리를 문제로 익힙니다.', 'quiz', '미들웨어'),
  (87, 'DB 내부 이해: 격리 수준, MVCC, 로그, 인덱스, EXPLAIN', '데이터베이스가 동시성과 장애 복구를 어떻게 처리하는지 InnoDB 기준으로 정리합니다. 트랜잭션 격리 수준과 dirty·non-repeatable·phantom read, Read View 와 MVCC, undo·redo·binlog 로그와 WAL, 크래시 복구 시 2단계 커밋, 복합 인덱스의 leftmost prefix 와 EXPLAIN 읽기를 문제로 익힙니다.', 'quiz', '데이터베이스'),
  (88, '설정 파일 읽고 고치기: Kafka, Prometheus, Elasticsearch', 'Kafka 의 리스너 설정, Prometheus 의 scrape 설정, Elasticsearch 의 ILM 정책 JSON 을 빈칸으로 채워 읽고, 설정을 안전하게 바꾸는 순서를 익힌 뒤, 샌드박스에서 설정 파일의 오류를 직접 찾아 고칩니다. 객관식뿐 아니라 빈칸, 순서, 직접 수정으로 구성했습니다.', 'linux', '미들웨어'),
  (89, 'Kafka 명령과 출력 다루기: 만들고, 읽고, 계산하기', 'Kafka 를 다루는 CLI 명령(토픽 생성, 컨슈머 그룹 조회)과 Debezium 커넥터 설정을 빈칸으로 채워 익히고, offset 재설정의 안전한 순서를 놓아 보고, 컨슈머 lag 과 ISR 이 모자란 파티션을 샘플 출력에서 awk 로 직접 계산해 봅니다. 객관식, 빈칸, 순서, 터미널 실습을 섞었습니다.', 'linux', '미들웨어'),
  (90, '관측 쿼리와 설정 다루기: PromQL, LogQL, 메트릭 읽기', 'Prometheus 의 PromQL 과 Loki 의 LogQL 을 빈칸으로 채워 읽고, 장애를 메트릭 → 로그 → 트레이스로 좁혀 가는 순서를 놓고, Prometheus 가 노출하는 텍스트 형식의 메트릭을 grep·awk 로 직접 읽고 계산하며 알림 규칙의 오류를 고칩니다. 카디널리티가 왜 위험한지도 직접 세어 봅니다.', 'linux', '미들웨어'),
  (91, 'MariaDB 복제·Galera 점검하기: 명령 채우고, 상태 읽고, 설정 고치기', 'MariaDB 복제와 Galera 를 점검하는 명령(dump 옵션, GTID 재연결, wsrep 상태 확인)을 빈칸으로 채우고, 쿼럼을 잃었을 때 복구 순서를 놓고, 복제 상태 출력과 dump 파일에서 필요한 값을 직접 뽑아 읽고, AUTO_INCREMENT 설정의 오류를 고칩니다. 객관식, 빈칸, 순서, 터미널 실습을 섞었습니다.', 'linux', '데이터베이스'),
  (92, '서비스 메시 YAML 읽고 고치기: Gateway, VirtualService', 'Istio 같은 서비스 메시에서 외부 트래픽을 받는 Gateway 와 요청을 나누는 VirtualService 의 YAML 을 빈칸으로 채워 읽고, 새 서비스를 노출하는 순서를 놓고, 이름 오타와 가중치 합계 같은 흔한 오류를 직접 고칩니다. 객관식, 빈칸, 순서, 터미널 실습을 섞었습니다.', 'linux', '미들웨어'),
  (93, 'Jenkins 운영 실무: PVC 속 결과물 찾기, 도구 컨테이너로 git 쓰기', '쿠버네티스에서 Jenkins 를 운영할 때 자주 부딪히는 일을 익힙니다. 빌드 결과물이 들어 있는 PVC 폴더를 찾는 흐름(Pod → PVC → PV → 실제 경로), agent Pod 방식에서 workspace 가 어디에 있는지, PVC 가 가득 찼을 때 큰 job 찾기, 그리고 호스트에 git 이 없을 때 git 이 든 컨테이너 이미지로 소스를 다루는 방법과 dubious ownership 오류를 다룹니다.', 'linux', '미들웨어'),
  (94, 'Git 처음부터 올리기: init, remote add, push 와 첫 오류들', 'Git 설정이 하나도 안 된 새 환경에서 `git init` → 사용자 설정 → `git remote add` → `git add` → `git commit` → `git push -u` 까지 처음부터 끝까지 해 보는 흐름을 익힙니다. 현장에서 가장 자주 만나는 첫 오류(사용자 미설정, 브랜치 이름 불일치, remote 중복, 첫 push 거절)와 .gitignore 를 처음 add 전에 정하는 습관까지 다룹니다. 원격은 샌드박스 안의 저장소로 대신합니다.', 'linux', 'Git'),
  (95, 'Git 문제 해결 상황집: 막혔을 때 빠져나오는 법', '현장에서 Git 이 막혔을 때 빠져나오는 법을 상황별로 익힙니다. 병합·rebase 를 중단하고 되돌리기, detached HEAD 에서 작업 살리기, 잘못된 브랜치에 한 커밋 옮기기, `.gitignore` 를 넣어도 계속 추적되는 파일 풀기, 삭제한 브랜치 복구, 문자열이 언제 들어왔는지 찾기, 비밀 정보를 커밋했을 때의 대응을 문제와 실습으로 다룹니다.', 'linux', 'Git'),
  (96, 'Git .gitignore: 올리면 안 되는 파일 다루기', '비밀 파일·빌드 산출물·로그를 저장소에 올리지 않는 법을 익힙니다. 패턴 문법(`*`, 폴더 `/`, 예외 `!`), 이미 추적 중인 파일을 `git rm --cached` 로 끊기, 어떤 규칙이 무시하는지 `git check-ignore -v` 로 찾기, 전역 무시 파일, 빈 폴더를 `.gitkeep` 으로 남기는 법을 문제와 실습으로 다룹니다.', 'linux', 'Git'),
  (97, '도커 문제 해결 상황집: 컨테이너가 안 뜰 때', '컨테이너가 바로 종료되거나, 포트가 충돌하거나, 디스크가 가득 찰 때 원인을 찾아 해결하는 법을 익힙니다. docker ps -a·logs·inspect 로 조사하고, 종료 코드 읽기, 포트·이름 충돌 풀기, 환경 변수 누락 고치기, 쌓인 컨테이너 정리, 재시작 정책을 문제와 실습으로 다룹니다.', 'docker', '도커'),
  (98, 'HAProxy 문제 해결 상황집: 503, DOWN, 안 뜰 때', '로드밸런서가 503 을 돌려주거나, 서버가 DOWN 이거나, 설정을 적용하지 못할 때 원인을 찾아 고치는 법을 익힙니다. 503·502·504 구분, 헬스체크 실패 사유(Layer4/Layer7) 읽기, stats CSV 로 DOWN 서버 찾기, 설정 검사(-c)로 오타 잡기, 포트 충돌 피하기, 끊김 없는 재적용(-sf)을 문제와 실습으로 다룹니다.', 'linux', '미들웨어'),
  (99, 'Redis 접속과 키 관리: 조회, 삭제, 이름 짓기', 'redis-cli 로 서버를 점검하고 키를 안전하게 다루는 기본기를 익힙니다. PING·TYPE·TTL 확인, 자료형에 맞는 읽기, KEYS 대신 SCAN, DEL 과 UNLINK, FLUSHDB·FLUSHALL 의 위험, 키 이름 규칙, INFO keyspace 읽기, 비밀번호 인증과 DB 번호 선택을 문제와 실습으로 다룹니다.', 'linux', '데이터베이스'),
  (100, '동시성 기본기: 경쟁 상태, 락, 데드락, 멱등성', '여러 작업이 동시에 실행될 때 생기는 문제와 해결법을 익힙니다. 경쟁 상태(lost update)를 재현해 보고 flock 으로 막기, 중복 실행 방지, 데드락과 락 순서 통일, 낙관적·비관적 락, 멱등 키와 중복 이벤트 처리, 재시도와 백오프, 원자적 락(mkdir, SET NX)을 문제와 실습으로 다룹니다.', 'linux', '미들웨어'),
  (101, '이벤트 스트리밍 기본기: 컨슈머 그룹, 오프셋, 전달 보장, 순서', '이벤트 스트리밍(Kafka)을 안전하게 쓰기 위한 기본기를 익힙니다. 컨슈머 그룹과 리밸런싱, 오프셋 커밋과 자동 커밋의 함정, lag 읽기, at-least-once·at-most-once·exactly-once, 파티션 단위 순서와 키 설계, 멱등한 처리, DLQ, Outbox 패턴을 빈칸·순서·객관식으로 다룹니다.', 'quiz', '미들웨어'),
  (102, 'Redis 문제 해결 상황집: OOM, 연결 거부, 느린 명령', 'Redis 가 쓰기를 거부하거나 느려지거나 연결이 안 될 때 원인을 찾아 해결하는 법을 익힙니다. OOM(maxmemory 와 eviction 정책), Connection refused 와 포트 찾기, SLOWLOG 로 느린 명령 찾기, 만료 없이 쌓이는 키 정리, 연결 한도와 붙잡힌 연결 끊기를 문제와 실습으로 다룹니다.', 'linux', '데이터베이스'),
  (103, 'Prometheus 알림 기본기: up, 알림 규칙, Alertmanager', 'Prometheus 로 서버를 감시하고 알림을 받는 기본기를 익힙니다. up 메트릭 읽기, 알림 규칙(expr, for, severity), 알림이 전달되는 흐름, 새 타깃 추가 절차, 히스토그램과 p95, Alertmanager 의 그룹핑·silence·라우팅을 빈칸·순서·객관식과 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (104, 'Prometheus 문제 해결 상황집: 타깃 DOWN, 빈 쿼리, 알림 안 옴', 'Prometheus 로 감시하다 막혔을 때 원인을 찾는 법을 익힙니다. Targets 에러(connection refused, context deadline exceeded, 401)로 원인 가르기, 쿼리가 빈 결과일 때 레이블 확인, 로그에서 가장 흔한 수집 에러 찾기, promtool 오류 읽고 규칙 고치기, 알림이 라우트에 안 맞아 전달되지 않는 문제를 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (105, '반복 입문: 같은 일을 컴퓨터에게 맡기기', '반복 작업 세트(35) 전에 가볍게 보는 입문입니다. 같은 일을 여러 번 시키는 이유, for 문의 모양, 와일드카드(*.log), seq, 한 줄씩 읽는 while read, 공백 파일 이름의 함정, 지우기 전에 echo 로 미리보기하는 습관을 문제로 익힙니다.', 'quiz', '리눅스'),
  (106, '이름으로 통신 입문: 이름표, 전화번호부, 포트', '이름으로 통신하기(36) 전에 가볍게 보는 입문입니다. 왜 이름이 필요한지, /etc/hosts 와 DNS 의 차이, 이름을 찾는 순서, 포트 번호, Name or service not known 과 Connection refused 의 차이, 접속 장애를 좁히는 순서를 문제로 익힙니다.', 'quiz', '리눅스'),
  (107, 'k8s 장애 읽기 입문: Pod 상태 한마디씩', '쉬운 장애 고치기(33) 전에 가볍게 보는 입문입니다. Running·Pending·ImagePullBackOff·CrashLoopBackOff 의 뜻, 막힌 Pod 를 보는 순서(get → describe → logs), Events 읽는 법, logs --previous, Pod 가 아니라 Deployment 를 고치는 이유를 문제로 익힙니다.', 'quiz', 'k8s'),
  (108, 'k8s 통신 입문: Pod IP, Service, 이름', '통신 방법 익히기(37) 전에 가볍게 보는 입문입니다. Pod 마다 IP 가 있다는 것, IP 가 바뀌는 이유, 그래서 Service 가 필요한 이유, 이름으로 접속하는 길, 레이블과 selector, port 와 targetPort, 다른 네임스페이스 이름, 외부 접속 방식을 문제로 익힙니다.', 'quiz', 'k8s'),
  (109, 'MariaDB 백업과 복원: 덤프 뜨고, 되살리고, 검증하기', 'MariaDB 를 안전하게 백업하고 복원하는 필수 기본기를 실제로 해 봅니다. mysqldump 로 덤프(--single-transaction)와 압축 덤프, 삭제된 DB 복구, 전체 덤프에서 테이블 하나만 복구, 새 DB 에 복원해 행 수 검증, 논리 백업과 물리 백업의 차이, 사용자·권한은 따로 옮겨야 하는 이유를 문제와 실습으로 다룹니다.', 'linux-db', '데이터베이스'),
  (110, 'Vault 입문: 비밀을 맡기는 금고', 'Vault 를 처음 만나는 입문입니다. Vault 가 무엇인지, Sealed/Unseal 과 unseal 키를 나눠 갖는 이유, 처음 시작하는 순서(init → unseal → login), root 토큰을 다루는 법, KV 에 비밀 넣고 꺼내기, 정책(최소 권한), 토큰 TTL, 앱이 비밀을 안전하게 쓰는 흐름을 문제로 익힙니다.', 'quiz', '미들웨어'),
  (111, 'Vault 백업과 복원: 스냅샷으로 되살리기', 'Vault 의 필수 운영 기본기입니다. 백업이 필요한 이유, raft snapshot save/restore, 스냅샷 파일을 민감하게 다루는 법, 복원 순서와 unseal 키 보관, cron 자동화, 백업을 다른 곳에 보관하기, 복원 연습, 유출된 비밀은 복원이 아니라 폐기·교체로 해결한다는 점을 문제로 익힙니다.', 'quiz', '미들웨어'),
  (112, 'Elasticsearch REST 기본기: curl 로 상태 보고 넣고 검색하기', 'Elasticsearch 를 curl 로 다루는 기본기를 익힙니다. 9200/9300 포트, _cat/health·_cat/indices 읽기, 문서 저장·조회 메서드, 색인 후 검색 순서, _search 응답(took, hits) 읽기, query DSL, 오류 응답(index_not_found_exception) 읽기, _bulk 형식 만들기를 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (113, 'Elasticsearch 문제 해결 상황집: yellow/red, 미할당 샤드, 디스크', 'Elasticsearch 가 yellow/red 가 되거나 쓰기가 막힐 때 원인을 찾아 해결하는 법을 익힙니다. 클러스터 진단 순서, yellow 와 red 의 의미, 디스크 워터마크 3단계, read-only 블록 해제, allocation/explain 읽기(NODE_LEFT, disk_threshold), 미할당 샤드 찾기, 오래된 인덱스 정리 명령 만들기를 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (114, 'Kafka 문제 해결 상황집: lag, 리밸런싱, 접속 오류, 복제, 디스크', 'Kafka 에서 자주 만나는 장애를 증상에서 원인으로 좁혀 가는 법을 익힙니다. 점검 명령, lag 출력 읽기(한 파티션만 밀릴 때), 접속 오류와 advertised 주소, poll 간격 초과, 리밸런싱 반복, 컨슈머 수와 파티션 수, poison pill 과 DLQ, under-replicated 대응, 디스크 가득 참, min.insync.replicas, 오프셋 리셋 주의점을 빈칸·순서·객관식으로 다룹니다.', 'quiz', '미들웨어'),
  (115, '동시성 문제 해결 상황집: stale 락, 중복 처리, 재시도 폭주', '동시성 문제가 실제로 터졌을 때 증상에서 원인을 좁히는 법을 익힙니다. 남은 pid 파일(stale 락) 확인과 정리, deadlock 오류 읽기, 같은 건이 두 번 처리될 때의 대응 순서, 작업 겹침 방지, 재시도 루프와 지수 백오프·jitter, 처리한 ID 기록으로 중복 막기, TTL 없는 분산 락의 위험을 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (116, 'CI/CD·레지스트리 문제 해결 상황집: push/pull 오류, 인증서, 빌드 로그', 'Jenkins·Nexus·Harbor 를 쓰다 만나는 장애를 증상에서 원인으로 좁히는 법을 익힙니다. 이미지 이름과 push 순서, unauthorized 와 denied 의 차이, 사설 CA 인증서 오류(x509), 413 업로드 제한, 릴리스 저장소의 재배포 거절, 빌드 로그에서 첫 실패 찾기, 오래된 태그 정리 목록 만들기, executor 대기 원인을 문제와 파일 실습으로 다룹니다.', 'linux', '미들웨어'),
  (117, '인프라 장애 상황집: 연결이 안 될 때 층별로 좁히기 (이름, 포트, 시간, MTU)', '서비스에 연결이 안 될 때 어느 층의 문제인지 좁히는 법을 익힙니다. ip·ss 로 내 쪽 확인, Could not resolve host 와 refused·timed out 의 차이, 오류 코드별 집계, 점검 순서, ss 출력에서 열린 포트 읽기, 죽은 nameserver 가 만드는 지연, 시스템 시간 오류가 일으키는 인증서 오류와 chrony 확인, 큰 전송만 멈추는 MTU 문제를 문제와 파일 실습으로 다룹니다.', 'linux', '인프라'),
  (118, 'Redis 백업과 복원: RDB 스냅샷, AOF, 복원 순서', 'Redis 데이터를 백업하고 복원하는 법을 직접 해 봅니다. SAVE·BGSAVE 의 차이, RDB 와 AOF 의 손실 범위, 서버를 저장 없이 내리고 파일을 교체하는 복원 순서, AOF 가 켜져 있을 때의 함정, 실행 중 AOF 켜기와 appendfsync 설정, 백업 파일 검사와 복원 리허설을 문제와 실습으로 다룹니다.', 'linux', '데이터베이스'),
  (119, 'k8s 권한(RBAC) 읽기: Role, RoleBinding, ServiceAccount', 'k8s 에서 누가 무엇을 할 수 있는지 정하는 RBAC 를 읽고 쓰는 법을 익힙니다. Role·RoleBinding·ServiceAccount 의 역할, Role 과 ClusterRole 의 차이, Role YAML, forbidden 오류 읽기, 권한을 주는 순서, auth can-i, RoleBinding 의 네임스페이스, 최소 권한 원칙, default 계정의 위험, 명령으로 만들기를 빈칸·순서·객관식으로 다룹니다.', 'quiz', 'k8s'),
  (120, 'k8s 클러스터 관리 읽기: etcd 백업·복원, 업그레이드, 인증서', '클러스터 관리자가 알아야 하는 작업의 절차와 판단을 읽기·순서·빈칸으로 익힙니다. etcd 가 중요한 이유, snapshot save/restore 와 인증 옵션, 복원 순서, kubeadm 업그레이드 규칙(마이너 한 단계씩, 컨트롤 플레인 먼저), 워커 노드 업그레이드 순서, 인증서 만료 확인과 갱신, static Pod 매니페스트 수정, etcd 외에 함께 보관할 것을 다룹니다. 샌드박스에 etcdctl 과 kubeadm 이 없어 직접 실행하지는 않습니다.', 'quiz', 'k8s'),
  (121, 'k8s 노드·컨트롤 플레인 장애 읽기: NotReady, kubelet, apiserver', '노드와 컨트롤 플레인 장애를 증상에서 원인으로 좁히는 법을 익힙니다. describe node 의 Conditions 읽기, cni plugin not initialized 와 Kubelet stopped posting node status 의 의미, NotReady 대응 순서, apiserver 연결 거부, 스케줄러 중단으로 인한 Pending, 컨트롤 플레인 점검 위치, DiskPressure 와 Evicted, cordon 과 uncordon, apiserver 가 죽었을 때 crictl 사용을 다룹니다.', 'quiz', 'k8s'),
  (122, 'k8s 스토리지 개념: PV, PVC, StorageClass, 접근 모드', 'k8s 저장소의 개념을 읽고 판단하는 법을 익힙니다. PV 와 PVC 의 역할, WaitForFirstConsumer 와 no persistent volumes available 이벤트 읽기, accessModes(RWO·RWX)와 Multi-Attach, reclaimPolicy 와 데이터 보호, 동적 프로비저닝 흐름, emptyDir 과 hostPath, PVC 마운트 YAML, 볼륨 확장과 StorageClass 설정을 빈칸·순서·객관식으로 다룹니다.', 'quiz', 'k8s'),
  (123, 'cron 작업 예약: 문법, 환경 차이, 로그, 겹침 방지', '정기 작업을 cron 으로 안전하게 예약하는 법을 익힙니다. 다섯 칸 문법(분 시 일 월 요일), */N 간격, 터미널과 cron 의 환경 차이(PATH), crontab 한 줄 직접 쓰기, 출력·오류 로그 남기기, % 이스케이프, flock 으로 겹침 방지, 등록 절차, 실행 여부 확인, crontab -r 의 위험을 문제와 파일 실습으로 다룹니다.', 'linux', '리눅스'),
  (124, 'SSH 접속 문제 해결 상황집: publickey, 권한, 호스트 키, 설정 파일', 'SSH 접속이 안 될 때 원인을 좁히는 법을 익힙니다. ssh -v 읽기, Permission denied (publickey), 호스트 키 변경 경고와 ssh-keygen -R, .ssh 폴더와 키 파일 권한(700/600), 서버의 bad ownership or modes 로그, 점검 순서, Too many authentication failures 와 IdentitiesOnly, ~/.ssh/config 별칭, 비밀번호 로그인 차단 전 주의점을 문제와 파일 실습으로 다룹니다.', 'linux', '리눅스'),
  (125, 'DB 기초 1 (개념): 데이터베이스와 테이블 구경하기', 'SQL 을 처음 만나는 사람을 위한 문제 모음입니다. 행과 열, 데이터베이스·테이블 목록 보기(SHOW, USE), 테이블 구조 읽기(DESC, PRI, NULL), SELECT 의 기본 모양, 필요한 열만 고르기, LIMIT 로 맛보기, 별명(AS), 세미콜론과 주석, 운영 DB 에서 안전하게 구경하는 순서를 짧은 문제로 반복해서 익힙니다.', 'quiz', '데이터베이스'),
  (126, 'DB 기초 1 (실습): 직접 쳐 보며 구경하기', 'MariaDB 에 접속해 데이터베이스와 테이블을 직접 구경해 봅니다. 데이터베이스·테이블 목록 저장, DESC 로 구조 읽기, SELECT 와 LIMIT, 필요한 열 고르기, 별명(AS), mariadb -N 으로 값만 뽑기, 현재 데이터베이스 확인을 작은 실습으로 다룹니다.', 'linux-db', '데이터베이스'),
  (127, '파일과 폴더 명령 한 줄씩', '리눅스의 가장 기본 명령을 한 줄 개념씩 반복합니다. pwd·ls·cd·mkdir·touch·cp·mv·rm·cat·less·head 의 뜻, ls -l 첫 글자와 숨김 파일, ~ 와 ., .., 자주 쓰는 옵션(-p, -r, -l, -a, -h, -f), 덮어쓰기(>)와 덧붙이기(>>), find -name 과 grep -i, 파일 다루는 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', '리눅스'),
  (128, '용어와 kubectl 기본 명령 한 줄씩', 'k8s 의 기본 용어와 kubectl 명령을 한 개념씩 반복합니다. Pod·Deployment·Service·Namespace·Node 의 역할, READY 와 Pending·ImagePullBackOff·CrashLoopBackOff 읽기, label 과 replicas, get·describe·logs·apply·create·scale·exec·expose·rollout·delete 명령과 -n·-o wide·-A 옵션, 배포하고 확인하는 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', 'k8s'),
  (129, '권한, 프로세스, 용량, 텍스트 도구 한 줄씩', '리눅스 운영의 기본 개념을 한 개념씩 반복합니다. rwx 와 숫자 권한(755, 644), 실행 권한과 Permission denied, chown 과 sudo, PID·ps·kill·kill -9, Ctrl+C 와 &, df 와 du 와 free, 파이프, wc·sort·uniq -c·cut·head 와 로그 에러 개수 세기, 문제 해결 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', '리눅스'),
  (130, 'YAML 필드와 Pod 상태 읽기', 'k8s YAML 과 상태 표시를 한 개념씩 반복합니다. 들여쓰기와 목록, apiVersion·kind·metadata·spec, selector 와 라벨 일치, replicas·image·containerPort·env, requests 와 limits, Service 의 selector·port·targetPort·type, OOMKilled·Evicted·Completed·RESTARTS·FailedScheduling 읽기, kubectl explain 과 dry-run, 점검 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', 'k8s'),
  (131, '네트워크 기본과 텍스트 도구 한 줄씩', '리눅스 네트워크와 텍스트 처리의 기본을 한 개념씩 반복합니다. IP·포트·localhost·DNS, ping·curl·ss·nc·ip addr 의 쓰임과 refused 읽기, grep -v/-c/-r/-n, sort -nr·uniq -c, sed 치환, awk 칸 뽑기, tee, 연결이 안 될 때와 로그에서 IP 별 접속 수 세기의 점검 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', '리눅스'),
  (132, '네임스페이스, ConfigMap, Secret 한 줄씩', 'k8s 의 구역과 설정 분리를 한 개념씩 반복합니다. Namespace 의 쓰임과 -n·기본 네임스페이스·다른 네임스페이스의 Service 부르기, ConfigMap 과 Secret 의 차이와 base64 가 암호화가 아닌 이유, 환경 변수 주입(configMapKeyRef·secretKeyRef)과 파일 마운트, CreateContainerConfigError, label 과 annotation, 안전하게 정리하는 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', 'k8s'),
  (133, '쉘 스크립트, 서비스, 압축 한 줄씩', '리눅스 운영에 자주 쓰는 도구를 한 개념씩 반복합니다. 쉘 스크립트의 shebang·실행 권한·변수·인자($1)·종료 코드($?)·&& 와 ||·set -e, systemctl 의 start·enable·status·restart·daemon-reload 와 journalctl -u, tar 로 압축·풀기·목록 보기(-czf, -xzf, -tzf, -C), 그리고 스크립트 작성, 서비스 장애 점검, 압축 백업의 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', '리눅스'),
  (134, 'Deployment 업데이트, Job, 상태 읽기 한 줄씩', 'k8s 워크로드 운영의 기본을 한 개념씩 반복합니다. Deployment 롤링 업데이트(maxSurge·maxUnavailable)와 rollout status·history·undo·restart, 멈춘 업데이트 읽기, Job·backoffLimit·restartPolicy·Completed, CronJob 과 cron 5칸, describe 의 Events·logs --previous·get -o wide/yaml/-w 로 상태 읽기, 그리고 업데이트와 롤백, Job 실행, 재시작 조사, CronJob 확인의 순서를 짧은 객관식·빈칸·순서 문제로 익힙니다.', 'quiz', 'k8s'),
  (135, '사용자와 그룹, 환경 변수, 패키지, 마운트 한 줄씩', '리눅스 서버 관리의 기본을 한 개념씩 반복합니다. id·/etc/passwd·UID 0·useradd·passwd·usermod -aG 와 su·sudo, 환경 변수 PATH 와 command not found·export·~/.bashrc·source, dnf·apt 의 install·search·update, lsblk·/etc/fstab·mount -a 를 짧은 객관식·빈칸·순서 문제로 익히고, 사용자 만들기, PATH 문제 풀기, 패키지 설치, fstab 안전하게 고치기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (136, 'Service 종류, 헬스 체크, 스케줄링, 스토리지 읽기 한 줄씩', 'k8s 네트워크·점검·배치·저장소의 기본을 한 개념씩 반복합니다. Service 의 ClusterIP·NodePort·LoadBalancer 와 Endpoints 읽기, Ingress 와 Controller, readinessProbe 와 livenessProbe 의 차이, nodeSelector·Insufficient cpu·cordon·uncordon 으로 Pending 읽기, PV·PVC·StorageClass 와 accessModes 를 짧은 객관식·빈칸·순서 문제로 익히고, Endpoints 가 빈 경우, READY 0/1, Pending Pod, Pending PVC 의 조사 순서를 연습합니다.', 'quiz', 'k8s'),
  (137, '이미지, 컨테이너, docker run 옵션 한 줄씩', '도커의 가장 기본 명령을 한 개념씩 반복합니다. docker run 이 하는 일, -d·--name·-p·-e·-v·--rm·-it 옵션의 뜻과 호스트:컨테이너 순서, 이미지 태그와 latest, pull·ps -a·logs -f·exec·stop·rm·rmi 의 쓰임, run 과 exec 의 차이를 짧은 객관식·빈칸·순서 문제로 익히고, 실행과 확인, 정리, 안 뜨는 컨테이너 조사, 폴더와 환경 변수를 붙여 실행하는 순서를 연습합니다.', 'quiz', '도커'),
  (138, '기록하고, 갈라지고, 합치고, 되돌리기 한 줄씩', 'Git 의 가장 기본 개념과 명령을 한 개념씩 반복합니다. 작업 폴더·스테이징·저장소의 흐름, init·add·commit·status·diff --staged·log --oneline, 브랜치와 HEAD, switch·merge 와 충돌 표시 읽기, fetch 와 pull 의 차이, push 거절 대처, restore --staged·stash pop·reset --hard 의 위험·revert, .gitignore 를 짧은 객관식·빈칸·순서 문제로 익히고, 첫 커밋, 브랜치 작업과 병합, 협업의 하루 흐름, 충돌 해결의 순서를 연습합니다.', 'quiz', 'Git'),
  (139, 'DB 기초 2 (개념): 조건과 정렬로 원하는 행만 골라 보기', 'SQL 로 원하는 행만 골라 보는 방법을 한 개념씩 반복합니다. WHERE 의 역할과 문자열 따옴표(Unknown column 오류), =·<>·AND·OR·IN·LIKE·%·BETWEEN, NULL 은 IS NULL 로 찾기, ORDER BY 의 ASC·DESC, ORDER BY DESC LIMIT 1 로 최댓값 행 찾기, DISTINCT, SELECT 절의 쓰는 순서를 짧은 객관식·빈칸·순서 문제로 익히고, SELECT 조립과 조건을 하나씩 좁혀 가기, 오류 풀기의 순서를 연습합니다.', 'quiz', '데이터베이스'),
  (140, 'DB 기초 3 (개념): 집계와 묶기로 숫자 요약하기', 'SQL 로 숫자를 요약하는 방법을 한 개념씩 반복합니다. COUNT(*) 와 COUNT(컬럼)의 NULL 차이, SUM·AVG·MIN·MAX, GROUP BY 로 묶어 집계하기, WHERE 와 HAVING 의 차이, 조건에 맞는 행이 없을 때의 0 과 NULL, AS 별칭과 ORDER BY, COUNT(DISTINCT), SELECT 절의 쓰는 순서를 짧은 객관식·빈칸·순서 문제로 익히고, 도시별 고객 수, 합계가 큰 고객 찾기, 집계 결과 점검, Invalid use of group function 오류 풀기의 순서를 연습합니다.', 'quiz', '데이터베이스'),
  (141, 'DB 기초 4 (개념): JOIN 으로 두 테이블 이어서 보기', '두 테이블을 이어서 보는 JOIN 을 한 개념씩 반복합니다. 테이블을 나누는 이유와 외래키, JOIN ... ON 으로 짝짓기, ON 을 빼먹으면 생기는 곱집합(15행), INNER JOIN 과 LEFT JOIN 의 결과 차이와 NULL 읽기, LEFT JOIN + IS NULL 로 짝 없는 행 찾기, 겹치는 컬럼의 ambiguous 오류와 테이블 별칭, JOIN + GROUP BY 합계, COUNT(*) 와 COUNT(o.id) 의 차이를 짧은 객관식·빈칸·순서 문제로 익히고, JOIN 쿼리 조립과 결과가 이상할 때의 점검 순서를 연습합니다.', 'quiz', '데이터베이스'),
  (142, '볼륨, 네트워크, 이미지 만들기, 정리 한 줄씩', '도커 운영에 자주 쓰는 명령을 한 개념씩 반복합니다. 볼륨과 바인드 마운트의 차이, 컨테이너를 지워도 남는 데이터, 사용자 정의 네트워크에서 이름으로 통신하기와 기본 네트워크의 한계, 컨테이너 안의 localhost, docker build 의 빌드 컨텍스트와 Dockerfile 줄 순서(캐시), tag·push, --restart unless-stopped, inspect·cp·logs --tail·system df, system prune 의 주의점을 짧은 객관식·빈칸·순서 문제로 익히고, 볼륨으로 데이터 지키기, 네트워크 연결, 이미지 빌드, 디스크 정리의 순서를 연습합니다.', 'quiz', '도커'),
  (143, '설정, 복제, 이력 다루기 한 줄씩', 'Git 을 일상에서 쓸 때 자주 만나는 개념과 명령을 한 개념씩 반복합니다. user.name·user.email 설정, clone 과 origin·remote -v, fast-forward 병합, branch -d 와 -D, commit --amend 와 push 후의 주의, show·blame·reflog 로 이력 읽기와 복구, tag, cherry-pick, reset --soft 와 --hard 의 차이, rebase 와 merge 의 차이를 짧은 객관식·빈칸·순서 문제로 익히고, 처음 설정과 복제, 마지막 커밋 메시지 고치기, reset 후 되살리기, 릴리스 표시의 순서를 연습합니다.', 'quiz', 'Git'),
  (144, '로그 읽기, 파일 찾기, 링크, inode, 신호 한 줄씩', '리눅스 서버에서 문제를 찾을 때 자주 쓰는 도구를 한 개념씩 반복합니다. /var/log, journalctl -p·--since, dmesg, 압축된 로그(zcat·zgrep), less 안의 검색, find 의 -name 따옴표·-type·-mtime·-size 부호, 심볼릭 링크와 하드 링크의 차이, df -i 와 inode, kill 과 kill -9 의 차이와 종료 코드, uptime 의 load average 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, 로그로 서비스 오류 찾기, 큰 파일 정리, 용량이 남는데 파일이 안 만들어질 때, 멈춘 프로세스 종료의 순서를 연습합니다.', 'quiz', '리눅스'),
  (145, '워크로드 관계, 리소스 단위, kubectl 작업 도구 한 줄씩', 'k8s 워크로드를 다루는 기본기를 한 개념씩 반복합니다. Deployment·ReplicaSet·Pod 의 관계와 Pod 를 지우면 되살아나는 이유, 업데이트 뒤 DESIRED 0 으로 남는 ReplicaSet, DaemonSet 과 StatefulSet, get all 의 범위, CPU 500m·1 과 메모리 Mi 단위, create 와 apply 의 차이, --dry-run=client -o yaml, exec·port-forward·top 을 짧은 객관식·빈칸·순서 문제로 익히고, Deployment 에서 Pod 까지 따라가기, YAML 뼈대 만들어 적용하기, Pod 안에서 확인하기, 임시 접속하기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (146, 'vi 편집기, ssh·scp, 날짜 형식, 방화벽, 서버 정보 한 줄씩', '서버에 접속해 파일을 고치고 옮길 때 자주 쓰는 도구를 한 개념씩 반복합니다. vi 의 명령 모드와 입력 모드, :wq·:q!, dd·u·yy·p, /검색, ssh user@host 의 모양과 -p·-i, scp 의 방향과 -P·-r(ssh 와 scp 의 포트 옵션 대소문자 차이), date +%Y-%m-%d 형식, 서비스는 LISTEN 인데 접속이 안 될 때의 방화벽 점검, /etc/os-release 와 uname 을 짧은 객관식·빈칸·순서 문제로 익히고, vi 로 파일 고치기, 원격에 파일 보내고 확인하기, 방화벽 점검, 서버 정보 파악의 순서를 연습합니다.', 'quiz', '리눅스'),
  (147, 'Helm 기본, 오토스케일(HPA), 이벤트·로그 읽기 한 줄씩', 'k8s 운영에서 자주 만나는 도구를 한 개념씩 반복합니다. Helm 의 chart 와 release 의 차이, repo add·install·--set·template·upgrade·history·rollback(롤백도 새 리비전)·uninstall, HPA 의 min~max 와 TARGETS 가 unknown 일 때의 원인, 컨테이너가 여러 개인 Pod 의 logs -c, get events --sort-by 를 짧은 객관식·빈칸·순서 문제로 익히고, 설치하고 확인하기, 업그레이드 후 되돌리기, 설치 전 점검, HPA unknown 점검의 순서를 연습합니다.', 'quiz', 'k8s'),
  (148, 'compose 운영 명령, Dockerfile 한 줄, 자원 제한, 상태 점검 한 줄씩', '도커를 운영하며 자주 쓰는 명령과 Dockerfile 줄을 한 개념씩 반복합니다. docker compose 의 ps·logs·stop 과 down 의 차이·down -v 의 위험·restart·exec·config, .dockerignore 와 .gitignore 의 차이, Dockerfile 의 ENV·WORKDIR·USER, --memory 한도와 OOMKilled(종료 코드 137), docker stats --no-stream, healthcheck 와 (healthy) 를 짧은 객관식·빈칸·순서 문제로 익히고, compose 서비스 점검, 볼륨은 남기고 내렸다 올리기, 메모리 부족 컨테이너 조사, .dockerignore 로 빌드 정리의 순서를 연습합니다.', 'quiz', '도커'),
  (149, '이력 비교, 변경 정리, stash, 원격 연결 한 줄씩', 'Git 으로 작업을 정리하고 문제를 추적하는 방법을 한 개념씩 반복합니다. log main..feature 와 --author·--stat·-- 경로, diff 와 diff --staged·diff HEAD 의 차이, restore 로 변경 버리기, clean -n 시험 실행, rm 과 rm --cached, mv, stash 가 담는 것과 -u·pop 과 apply 의 차이, push -u 와 branch -vv, bisect 를 짧은 객관식·빈칸·순서 문제로 익히고, 급한 수정 때 stash 하기, 새 브랜치를 원격에 연결하기, 추적하지 않는 파일 안전하게 정리하기, bisect 로 문제 커밋 찾기의 순서를 연습합니다.', 'quiz', 'Git'),
  (150, '와일드카드, 따옴표, 명령 연결, 텍스트 도구 한 줄씩', '쉘의 기본 문법과 텍스트 도구를 한 개념씩 반복합니다. *·?·[ ] 와일드카드와 일치하는 파일이 없을 때의 동작, 중괄호 확장, 작은따옴표와 큰따옴표의 차이, $( ) 명령 치환, 따옴표 없는 공백과 공백이 든 파일 이름, ;·&&·|| 의 차이, cut -d -f, tr, sort -u, xargs, diff 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, 코드별 개수 세기, 와일드카드로 안전하게 지우기, 설정 파일 비교, 공백 이름 문제 풀기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (151, 'Pod 수명주기, 이미지 정책, 라벨 셀렉터, 출력 고르기 한 줄씩', 'Pod 가 시작되고 끝나는 과정과 라벨로 고르는 방법을 한 개념씩 반복합니다. init 컨테이너와 Init:0/1 읽기, restartPolicy 의 Always·OnFailure·Never 와 Completed, imagePullPolicy 기본값과 IfNotPresent 의 함정, terminationGracePeriodSeconds 와 삭제가 30초 걸리는 이유, 라벨 셀렉터의 in·!=·존재·부재·쉼표(AND), custom-columns, scale 을 짧은 객관식·빈칸·순서 문제로 익히고, Init 에서 멈춘 Pod, 재시작하지 않는 Pod, 라벨로 좁히기, 삭제가 느릴 때의 조사 순서를 연습합니다.', 'quiz', 'k8s'),
  (152, '쉘 스크립트 조건, 반복, 함수, 백그라운드 한 줄씩', '쉘 스크립트의 제어 구조를 한 개념씩 반복합니다. [ ] 검사(-f·-d·-z·-n), 숫자(-gt)와 문자열(=) 비교의 차이, 대괄호 사이 공백과 빈 변수 따옴표 오류, if·fi, for 와 와일드카드, 무한 반복 막기, continue·break, $(( )) 정수 산술, 함수의 return·local, $#·$@·$0·shift, case, &·$!·wait 를 짧은 객관식·빈칸·순서 문제로 익히고, 파일 검사 스크립트, 로그 압축 반복문, 백그라운드 작업 다루기, 대괄호 오류 풀기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (153, '자원 한도(Quota), 컨테이너 보안 기본, ServiceAccount, 비공개 이미지 한 줄씩', '여러 사람이 쓰는 클러스터를 안전하게 운영하는 기본기를 한 개념씩 반복합니다. ResourceQuota 와 exceeded quota 오류, must specify requests 오류와 LimitRange 의 기본값, Quota 와 LimitRange 의 차이, securityContext 의 runAsNonRoot·runAsUser·readOnlyRootFilesystem, ServiceAccount 와 토큰 마운트 끄기, imagePullSecrets 와 ImagePullBackOff 를 짧은 객관식·빈칸·순서 문제로 익히고, quota 거부 조사, requests 오류 풀기, root 이미지 보안 적용, 비공개 레지스트리 이미지 쓰기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (154, 'Dockerfile 심화, 변수와 명령, 멀티스테이지, 이미지 옮기기 한 줄씩', 'Dockerfile 과 이미지를 다루는 기본기를 한 개념씩 반복합니다. COPY 와 ADD 의 차이, ARG 와 ENV(빌드 때만 보이는 변수), --build-arg, CMD 의 쉘 형식과 exec 형식, CMD 와 ENTRYPOINT 의 차이와 함께 쓸 때의 인자, --entrypoint, 멀티스테이지 빌드로 이미지 줄이기, 같은 RUN 에서 지워야 크기가 주는 이유, docker history, save 와 load 로 이미지 옮기기, --env-file 을 짧은 객관식·빈칸·순서 문제로 익히고, 빌드 변수 확인, 멀티스테이지로 줄이기, 인터넷 없는 서버로 옮기기, 큰 이미지 원인 찾기의 순서를 연습합니다.', 'quiz', '도커'),
  (155, '병합 방식, 원격 관리, detached HEAD, 안전한 푸시 한 줄씩', '팀으로 Git 을 쓸 때 만나는 개념과 명령을 한 개념씩 반복합니다. merge 의 --no-ff·--squash·--abort 와 충돌 상태 UU, remote -v·set-url, branch -r·-a, push --delete 와 fetch --prune, detached HEAD 와 작업 구하기, pull 과 pull --rebase 의 차이, --force-with-lease 와 --force, 태그를 따로 올리는 것을 짧은 객관식·빈칸·순서 문제로 익히고, 스쿼시 병합, 병합 중단, detached HEAD 에서 작업 구하기, push 거절을 rebase 로 풀기의 순서를 연습합니다.', 'quiz', 'Git'),
  (156, '네트워크 읽기(경로, DNS, curl, LISTEN)와 텍스트 도구 심화 한 줄씩', '서버의 네트워크 문제를 읽는 도구와 텍스트 도구의 옵션을 한 개념씩 반복합니다. ip route 의 default via 와 게이트웨이가 없을 때의 증상, resolv.conf 의 nameserver 와 getent hosts, curl 의 상태 코드와 -f·-m·-I·-v 및 종료 코드 7·6·28, ss 의 LISTEN 주소(127.0.0.1 과 0.0.0.0 의 차이), grep 의 -i·-l·-w·-A/-B/-C, awk 의 조건과 합계, sort -k·-n, tail -n +2 를 짧은 객관식·빈칸·순서 문제로 익히고, 이름→경로→응답 점검, 로그 에러 맥락 보기, 표의 합계·평균, 헤더 있는 CSV 의 최댓값 찾기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (157, '배포 전략, 설정 반영 시점, 삭제 연쇄, 노드·DNS 읽기 한 줄씩', 'k8s 운영 중 헷갈리기 쉬운 동작을 한 개념씩 반복합니다. 기본 RollingUpdate(25%)와 Recreate 의 차이와 쓰임, 롤링 중 두 버전이 함께 도는 것, ConfigMap 을 바꿨을 때 환경 변수·볼륨·subPath 가 반영되는 시점과 rollout restart, emptyDir 의 수명, Deployment 삭제의 연쇄와 --cascade=orphan, 노드의 Capacity·Allocatable·Conditions 읽기, 클러스터 DNS 이름(서비스.네임스페이스.svc.cluster.local)을 짧은 객관식·빈칸·순서 문제로 익히고, 설정 반영 안 될 때, bad address 풀기, 고아로 지우기, 노드 상태 점검의 순서를 연습합니다.', 'quiz', 'k8s'),
  (158, 'DB 기초 5 (개념): 운영자가 자주 쓰는 SQL, 세션·설정·권한·실행 계획', 'MariaDB 를 운영할 때 가장 먼저 쓰는 SQL 을 한 개념씩 반복합니다. SHOW PROCESSLIST 와 FULL, Time 열 읽기, KILL QUERY 와 KILL 의 차이(연결 유지 여부), SHOW VARIABLES 와 STATUS 의 차이, SET GLOBAL 이 재시작하면 사라지는 것, CREATE USER·GRANT·SHOW GRANTS·REVOKE 와 ERROR 1142, 계정 이름@위치와 USER()·CURRENT_USER(), information_schema 로 DB 크기 보기, EXPLAIN 의 type 과 인덱스를 못 쓰는 조건을 짧은 객관식·빈칸·순서 문제로 익히고, 느린 쿼리 중단, 앱 전용 계정 만들기, 권한 오류 풀기, 인덱스로 느린 조회 개선하기의 순서를 연습합니다.', 'quiz', '데이터베이스'),
  (159, 'DB 기초 6 (개념): 데이터 바꾸기와 트랜잭션, INSERT·UPDATE·DELETE 안전하게', '데이터를 추가·수정·삭제하는 SQL 과 그 안전 습관을 한 개념씩 반복합니다. INSERT 의 열 목록과 ERROR 1136·1062·1364·1048, AUTO_INCREMENT 와 TRUNCATE, WHERE 없는 UPDATE·DELETE 의 위험, Rows matched 와 Changed 의 차이, sql_safe_updates 안전 모드, DELETE 와 TRUNCATE 의 차이, START TRANSACTION·COMMIT·ROLLBACK, 다른 세션에서 보이는 시점과 행 잠금, autocommit, DDL 의 암묵적 커밋을 짧은 객관식·빈칸·순서 문제로 익히고, 안전하게 값 바꾸기, WHERE 를 빠뜨렸을 때의 대응, 안전 모드, DDL 함정의 순서를 연습합니다.', 'quiz', '데이터베이스'),
  (160, '종료 코드 읽기, 컨테이너 보안 기본, 레지스트리와 digest 한 줄씩', '컨테이너 문제를 읽고 안전하게 운영하는 기본기를 한 개념씩 반복합니다. 종료 코드 127(명령 없음)·126(실행 불가)·125(docker 오류)와 앱 종료 코드 전달, 137 이 항상 OOM 은 아니라는 점과 OOMKilled 확인, --user·--read-only(--tmpfs)·--cap-drop/--cap-add·--privileged 의 위험·no-new-privileges, docker diff 의 A·C·D 와 docker top·logs --since, 레지스트리 주소가 든 이름으로 tag·push 하기, 움직이는 태그와 고정된 digest 를 짧은 객관식·빈칸·순서 문제로 익히고, 바로 종료되는 컨테이너 조사, 단계적 보안 강화, 로컬 레지스트리에 올리기, 컨테이너 안 변경 살펴보기의 순서를 연습합니다.', 'quiz', '도커'),
  (161, '이력 다듬기, rebase 충돌, 병합 되돌리기, 무시 규칙, 이력 검색 한 줄씩', 'Git 이력을 다듬고 되돌리는 기술을 한 개념씩 반복합니다. reset 의 --soft·--mixed·--hard 차이, rebase -i 의 pick·squash·fixup·drop·reword 와 순서 바꾸기, rebase 충돌 때의 UU·--continue·--abort·--skip, rebase 뒤의 일직선 이력, 병합 커밋 revert -m 1, .gitignore 의 !·폴더·/ 패턴과 check-ignore -v, log --grep·-S·shortlog -sn HEAD, config 의 local 이 global 보다 우선하는 것과 alias 를 짧은 객관식·빈칸·순서 문제로 익히고, 커밋 하나로 정리, rebase 충돌 해결, 병합 되돌리기, drop 한 커밋 되살리기의 순서를 연습합니다.', 'quiz', 'Git'),
  (162, '성능 읽기, top·ps·free·vmstat 와 좀비 프로세스 한 줄씩', '서버 성능 화면을 읽는 기본기를 한 개념씩 반복합니다. top 의 Tasks·%Cpu(us·sy·id·wa)·메모리 줄, ps 의 STAT(R·S·D·Z·T)와 컬럼(%CPU·VSZ·RSS·TIME), VSZ 와 RSS 의 차이, --sort=-%cpu, %CPU 100 의 의미, 좀비 프로세스와 kill -9 로 안 죽는 이유, vmstat 의 첫 행·r·b·si·so, free 의 available 과 /proc/meminfo·/proc/loadavg 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, 서버가 느릴 때 좁혀 가기, CPU 와 입출력 대기 구분, 좀비 정리, 메모리 읽기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (163, 'StatefulSet 과 CronJob 운영: 번호가 붙는 Pod, 일정 작업 다루기', '이름·저장소·순서가 중요한 앱과 일정 작업을 다루는 기본기를 한 개념씩 반복합니다. StatefulSet 의 번호 붙은 Pod 이름과 시작·롤링 업데이트 순서, volumeClaimTemplates 의 Pod 별 PVC, Pod 를 지워도 데이터가 남는 이유, 스케일 다운과 삭제 뒤에 PVC 가 남는 것, Headless Service 와 serviceName, Deployment 와 StatefulSet 고르기, CronJob 의 기본값과 concurrencyPolicy(Allow·Forbid)·suspend·create job --from 과 get cronjob 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, StatefulSet 배포 확인, 데이터 유지 확인, CronJob 멈췄다 재개, 겹쳐 실행 막기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (164, 'DB 기초 7 (개념): 테이블 만들기, 제약·자료형·외래 키·ALTER', '테이블을 설계하고 만드는 SQL 을 한 개념씩 반복합니다. PRIMARY KEY(복합 키 포함)·NOT NULL·DEFAULT 와 NULL 의 차이·UNIQUE 와 NULL, VARCHAR 길이 초과(ERROR 1406)·자료형 불일치(1366)·없는 날짜(1292)·DECIMAL 범위(1264)와 반올림, 글자 수와 바이트 수, DECIMAL 과 FLOAT 의 오차, 외래 키의 ERROR 1452·1451 과 ON DELETE CASCADE·SET NULL, ALTER TABLE 로 열 추가·삭제·이름 바꾸기·길이 줄이기, IF NOT EXISTS·IF EXISTS 를 짧은 객관식·빈칸·순서 문제로 익히고, 테이블 설계해 만들기, 외래 키 오류 풀기, 운영 중 열 추가, Data too long 오류 풀기의 순서를 연습합니다.', 'quiz', '데이터베이스'),
  (165, '스케줄과 시간 읽기: cron 식, cron 의 환경, date 계산 한 줄씩', '정해진 시간에 일하는 작업과 날짜 계산의 기본기를 한 개념씩 반복합니다. cron 의 5개 필드와 *·*/n·범위·목록, 요일 숫자, 일과 요일을 모두 지정하면 OR 로 동작하는 것, cron 의 짧은 PATH 와 /bin/sh, % 이스케이프, 출력 리다이렉트와 작업 디렉터리, crontab 파일 끝 줄바꿈, date 의 에포크(+%s·-d @0)와 날짜 계산·윤년·invalid date, POSIX TZ 의 부호, timeout 의 종료 코드 124 를 짧은 객관식·빈칸·순서 문제로 익히고, cron 안전하게 등록하기, cron 에서만 실패하는 작업 풀기, 날짜 사이 일수 구하기, 멈추는 작업 막기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (166, 'NetworkPolicy 기초: 모두 막고 필요한 것만 열기, from 규칙 읽기', 'Pod 사이의 접속을 제어하는 기본기를 한 개념씩 반복합니다. 정책이 없을 때의 기본(모두 열림), podSelector 가 빈 default-deny 와 Ingress·Egress 의 차이, 허용 정책을 더하는 방식과 정책을 지웠을 때의 동작, from 의 podSelector·namespaceSelector 와 한 항목(AND)·두 항목(OR) 차이, ports 로 포트 제한하기, egress 를 막았을 때 DNS 가 함께 막히는 것과 53 포트 허용, 빈 규칙과 규칙 없음의 차이, get netpol 의 POD-SELECTOR 와 describe 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, 모두 막고 필요한 것만 열기, 접속이 막힌 원인 찾기, egress 를 막고 DNS 열기, 다른 네임스페이스 허용의 순서를 연습합니다.', 'quiz', 'k8s'),
  (167, '이미지 빌드 읽기: 빌드 컨텍스트, 레이어와 캐시, .dockerignore 한 줄씩', 'docker build 를 이해하는 기본기를 한 개념씩 반복합니다. 빌드 컨텍스트(.)와 COPY 가 컨텍스트 안의 파일만 복사하는 것, 레이어를 만드는 줄(RUN·COPY·ADD)과 크기 0B 인 설정 줄(ENV·CMD), 같은 빌드의 CACHED 와 한 단계가 바뀌면 뒤 단계가 모두 다시 실행되는 것, 자주 바뀌는 파일을 뒤에 복사하는 순서, --no-cache, .dockerignore 의 제외·! 예외·순서와 제외한 파일을 COPY 할 때의 not found, 컨텍스트 전송량, 뒤 줄에서 지워도 줄지 않는 이미지와 한 RUN 으로 합치기, ARG 와 ENV 의 차이, docker tag 가 같은 이미지에 이름만 붙이는 것을 짧은 객관식·빈칸·순서 문제로 익히고, 캐시를 살리는 Dockerfile 순서, .dockerignore 적용 확인, 큰 이미지 원인 찾기, 캐시 영향 확인의 순서를 연습합니다.', 'quiz', '도커'),
  (168, 'Git 객체와 이력 주소 읽기, 부분 스테이징, 브랜치 정리 한 줄씩', 'Git 이 이력을 저장하고 가리키는 방식을 한 개념씩 반복합니다. commit·tree·blob 객체와 cat-file, 커밋 객체의 tree·parent, 같은 내용은 같은 해시, ls-files 와 ls-tree, HEAD~1·HEAD^·HEAD^2 의 차이와 병합 커밋의 부모, describe 읽기, 경량 태그와 주석 태그, add -p 로 덩어리만 스테이징, branch --merged·--no-merged, switch - 와 오류 메시지, branch -vv 의 업스트림 표시, restore --source 와 --staged, status 의 두 글자 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, 커밋 구조 따라가기, 한 파일의 변경을 나눠 커밋하기, 병합된 브랜치 정리하기, 예전 파일 상태 되살리기의 순서를 연습합니다.', 'quiz', 'Git'),
  (169, '찾아서 처리하기: find 조건, -exec 와 xargs, tee·tr·uniq 한 줄씩', '파일을 찾아 한꺼번에 처리하는 기본기를 한 개념씩 반복합니다. find 의 -name 은 이름만 비교한다는 것과 -iname·-path, -type·-maxdepth·-mindepth, -size 의 올림과 바이트 단위, -empty, 부정(!)과 OR(-o)·괄호, -newer, -exec 의 세미콜론 형식과 + 형식의 실행 횟수 차이, -delete 를 조건 앞에 쓰면 전부 지워지는 위험, xargs 의 기본 동작과 공백이 든 이름의 문제, -print0 과 -0, -n·-r, tee 의 화면·파일 동시 출력과 -a, tr 로 글자 바꾸기·지우기, uniq 는 이웃한 줄만 합친다는 것과 sort | uniq -c 집계를 짧은 객관식·빈칸·순서 문제로 익히고, 안전하게 찾아서 지우기, 공백 이름 때문에 실패한 xargs 고치기, 가장 많이 나온 줄 찾기, 화면에 보면서 저장하고 이어 쓰기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (170, '자원 요청·한도 읽기: QoS 등급, CPU 스로틀링과 OOMKilled, 노드 예약 현황', 'Pod 의 자원 설정이 실제로 어떻게 동작하는지 한 개념씩 반복합니다. BestEffort·Burstable·Guaranteed 등급이 정해지는 규칙과 확인 방법, limits 만 쓰면 requests 가 같은 값으로 채워지는 것, cpu 만 쓰면 Guaranteed 가 아닌 것, limits 가 cpu.max·memory.max 로 적용되는 것, CPU 한도 초과는 스로틀링이고 메모리 한도 초과는 OOMKilled(종료 코드 137)이며 앱 로그에 남지 않는 것, requests 가 limits 보다 크면 거부되는 것과 requests 가 너무 크면 Pending 이 되는 것, 0.5 와 500m·Mi 와 M 의 단위, kubectl set resources 가 새 롤아웃을 만드는 것, top 의 실제 사용량과 describe node 의 예약량 차이를 짧은 객관식·빈칸·순서 문제로 익히고, OOMKilled 원인 찾기, 자원 부족 Pending 풀기, 한도 적용 확인, Deployment 자원 조정의 순서를 연습합니다.', 'quiz', 'k8s'),
  (171, '컨테이너 상태와 종료 신호: create·pause, stop 의 SIGTERM, PID 1, 포트 공개', '컨테이너가 살고 멈추는 과정을 한 개념씩 반복합니다. create·start·pause·stop 에 따른 Created·Up·Paused·Exited 상태, stop 이 SIGTERM 을 보내고 기본 10초 뒤 SIGKILL 하는 것, PID 1 이 신호를 처리하지 않을 때 10초가 걸리고 137 로 끝나는 것, --init 과 신호를 처리하는 앱, 쉘 형식과 exec 형식 CMD 의 PID 1, kill 과 -s 로 보내는 신호, start 와 run 의 차이, 실행 중인 컨테이너를 rm 할 때의 거부, docker wait, EXPOSE 는 공개가 아니라는 것과 -P·docker port, docker commit 을 짧은 객관식·빈칸·순서 문제로 익히고, 느린 stop 고치기, 상태 따라가기, 포트가 열리지 않을 때 확인, 컨테이너 변경을 이미지로 남기기의 순서를 연습합니다.', 'quiz', '도커'),
  (172, 'worktree, fixup, 범위 비교(.. 와 ...), 줄바꿈 정책, 서브모듈 기본 한 줄씩', '작업 폴더와 이력을 다루는 도구를 한 개념씩 반복합니다. worktree 로 같은 저장소의 폴더를 하나 더 만드는 것과 같은 브랜치를 두 곳에서 쓸 수 없는 것, worktree 에서의 커밋과 remove, commit --fixup 과 rebase --autosquash, merge-base, 두 점(..)과 세 점(...)의 log·diff 차이와 rev-list --left-right, CRLF 와 LF 그리고 ls-files --eol, core.autocrlf=input, .gitattributes 의 text·eol·binary 와 check-attr, 서브모듈의 .gitmodules 와 160000 포인터, 복제 뒤 비어 있는 서브모듈과 submodule update --init 을 짧은 객관식·빈칸·순서 문제로 익히고, 다른 브랜치를 동시에 작업하기, fixup 으로 앞 커밋 고치기, 줄바꿈 정책 적용하기, 서브모듈을 최신 커밋으로 올리기의 순서를 연습합니다.', 'quiz', 'Git'),
  (173, '권한 비트와 프로세스 한도: umask, setuid·sticky, nohup·nice, ulimit, /proc 한 줄씩', '파일 권한의 숨은 부분과 프로세스를 다루는 기본기를 한 개념씩 반복합니다. umask 로 새 파일과 폴더의 권한이 정해지는 계산과 적용 범위, setuid·setgid·sticky 비트의 표시와 대문자 S·T, 공유 폴더에서 남의 파일을 지울 수 있는지, nohup 이 SIGHUP 을 무시하게 하는 것, nice 의 값과 범위와 일반 사용자의 제한, renice, ulimit 의 소프트·하드 한도와 -n 100 및 -Sn 의 차이, CPU 시간과 파일 크기 한도에 걸렸을 때의 종료 코드, /proc/PID 의 fd·cmdline·cwd·exe·status, exec 와 env, heredoc 의 따옴표 차이를 짧은 객관식·빈칸·순서 문제로 익히고, umask 로 새 파일 권한 확인, nohup 작업 확인, 열린 파일 한도 시험, /proc 에서 프로세스 읽기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (174, 'kubectl 편집·조회 도구: label·annotate, patch, edit, diff, jsonpath, wait', '리소스를 고치고 골라 보고 기다리는 kubectl 도구를 한 개념씩 반복합니다. 라벨·어노테이션을 덮어쓸 때의 --overwrite 와 지우는 표기, selector 가 쓰는 라벨을 지웠을 때의 동작, Deployment 라벨과 Pod 템플릿 라벨의 차이, change-cause 와 rollout history, patch 의 전략적 병합·JSON 병합·JSON 패치와 목록 필드 처리 차이, kubectl edit 의 결과, set image 와 rollout restart, 적용 전 kubectl diff 와 종료 코드, explain, jsonpath·custom-columns·-o name, --field-selector 와 -l 의 차이, kubectl wait 의 condition met 과 시간 초과를 짧은 객관식·빈칸·순서 문제로 익히고, diff 로 확인하고 적용하기, JSON 패치로 복제 수 바꾸기, 라벨 다루기, 배포가 준비될 때까지 기다리기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (175, 'compose 읽기: 변수 우선순위, depends_on 조건, profiles, scale, 고아 컨테이너', 'docker compose 를 쓸 때 헷갈리는 동작을 한 개념씩 반복합니다. 변수 치환의 기본값(:-)과 필수 표시(:?)와 쉘·.env·기본값의 우선순위, environment 와 env_file 의 우선순위와 run -e, depends_on 의 기본 동작(시작 순서만 보장)과 service_healthy 조건, profiles 로 평소에는 꺼 두는 서비스와 --profile·COMPOSE_PROFILES, 프로젝트 이름과 컨테이너·네트워크 이름 규칙, --scale, run 과 --rm, up 을 다시 했을 때의 Running·Recreate 와 --force-recreate, 고아 컨테이너와 --remove-orphans, config --services 와 ls 를 짧은 객관식·빈칸·순서 문제로 익히고, 변수 우선순위 확인, DB 가 준비된 뒤 앱 시작, 디버그 서비스 켜기, 고아 컨테이너 정리의 순서를 연습합니다.', 'quiz', '도커'),
  (176, 'rebase --onto, cherry-pick 옵션, 덩어리 선택(-p), log 필터와 형식, 개인 무시 목록', '이력을 옮기고 골라 보는 도구를 한 개념씩 반복합니다. rebase --onto 로 일부 커밋만 새 기준 위로 옮기는 것과 일반 rebase 와의 차이, cherry-pick 의 -n·-x 와 충돌 시 --continue·--abort, restore -p 와 commit -p 로 덩어리만 되돌리거나 커밋하는 것, log 의 --first-parent·--merges·--no-merges, branch --contains 와 --no-contains, diff --word-diff, log --format 의 자리표시자, --diff-filter 로 삭제·추가·수정·이름 변경 걸러내기, .git/info/exclude 와 .gitignore 의 차이, revert -n, add -N 을 짧은 객관식·빈칸·순서 문제로 익히고, 일부 커밋만 새 기준으로 옮기기, cherry-pick 충돌 해결, 파일의 일부 변경만 버리기, 삭제된 파일 되살리기의 순서를 연습합니다.', 'quiz', 'Git'),
  (177, 'sed 와 awk 심화: 주소 범위, s 플래그, -i, 필드와 NR·NF, 배열·printf 한 줄씩', '텍스트를 고치고 집계하는 sed 와 awk 의 기본기를 한 개념씩 반복합니다. sed 의 -n 과 p, 줄 번호·패턴·범위·부정 주소, d 와 q, s 의 g·숫자·I 플래그, & 와 그룹과 -E, 구분자 바꾸기, -i 와 -i.bak 및 같은 파일로 리다이렉트하면 비워지는 것, 여러 파일과 -s, a·i·c 명령, awk 의 필드와 $NF·NF, 기본 구분자와 -F, 패턴·BEGIN·END·-v, 초기화하지 않은 변수와 n+0, OFS 와 $1=$1, 배열로 키별 개수·합계 구하기, printf 형식을 짧은 객관식·빈칸·순서 문제로 익히고, sed 로 안전하게 파일 고치기, CSV 부서별 합계, 로그의 가장 흔한 레벨 찾기, sed 로 범위 확인하고 지우기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (178, 'Job 심화와 스케줄링 제약: completions, TTL·deadline, taint·toleration, nodeAffinity, PDB', '일회성 작업과 Pod 배치 제약을 한 개념씩 반복합니다. Job 의 기본값(completions 1·parallelism 1·backoffLimit 6)과 completions·parallelism 의 동작, get job 의 STATUS·COMPLETIONS 열, ttlSecondsAfterFinished 의 자동 삭제, activeDeadlineSeconds 와 DeadlineExceeded, backoffLimit 초과(BackoffLimitExceeded), suspend 로 대기시켰다 시작하기, Job 삭제와 logs job/, 노드 taint 와 Pending(untolerated taint), toleration 의 Equal 과 Exists, taint 의 추가·제거 표기, nodeAffinity 의 required 와 preferred 와 연산자(In·NotIn·Exists)와 IgnoredDuringExecution, PodDisruptionBudget 의 ALLOWED DISRUPTIONS 를 짧은 객관식·빈칸·순서 문제로 익히고, Job 이 실패한 이유 읽기, Pending 의 스케줄링 원인 풀기, taint 로 노드 막고 풀기, Job 을 대기시켰다 시작하기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (179, '네트워크와 볼륨 심화: 사용자 정의 네트워크, 격리, 볼륨 수명, :ro, --mount, 익명 볼륨, tmpfs', '컨테이너의 통신과 저장을 한 개념씩 반복합니다. bridge·host·none 과 사용자 정의 네트워크, 사용자 정의 네트워크에서만 이름이 풀리는 것과 --network-alias, 네트워크 격리와 network connect·disconnect, 같은 네트워크에서는 -p 가 필요 없다는 것, 사용 중인 네트워크 삭제 오류, --internal 네트워크, 볼륨이 컨테이너보다 오래 사는 것과 volume inspect, 사용 중인 볼륨 삭제 오류, :ro 와 --mount 의 readonly, 빈 볼륨이 이미지 내용으로 채워지는 것과 바인드 마운트가 가리는 것, -v 와 --mount 가 없는 호스트 경로를 다루는 차이, 익명 볼륨과 rm -v, tmpfs 를 짧은 객관식·빈칸·순서 문제로 익히고, 컨테이너끼리 이름으로 통신하기, 볼륨에 데이터 남기고 이어 쓰기, 볼륨을 읽기 전용으로 점검하기, 사용 중인 네트워크 정리하기의 순서를 연습합니다.', 'quiz', '도커'),
  (180, 'Git 훅, archive, bundle, 잃은 커밋 찾기, notes, assume-unchanged 한 줄씩', 'Git 을 자동화하고 이력을 지키는 도구를 한 개념씩 반복합니다. .git/hooks 의 이름과 실행 권한, pre-commit 의 종료 코드로 커밋을 막는 것, --no-verify 로 건너뛰기, commit-msg 훅이 받는 메시지 파일, core.hooksPath 로 팀이 훅을 공유하는 것, pre-push 훅, git archive 가 담는 것과 --prefix·zip 형식, export-ignore, git bundle 의 create·verify·clone 과 기준 커밋이 필요한 범위 번들, blame -L 과 log -L, reset --hard 로 잃은 커밋을 reflog·fsck 로 찾아 되살리는 것과 reflog expire·gc 뒤에는 복구할 수 없는 것, git notes, assume-unchanged 와 skip-worktree 를 짧은 객관식·빈칸·순서 문제로 익히고, 훅으로 커밋 막아 보기, 잃은 커밋 되살리기, 저장소를 번들 파일로 옮기기, 공백 문제 확인하고 커밋하기의 순서를 연습합니다.', 'quiz', 'Git'),
  (181, '압축과 파일 검증: gzip·tar·zip, 체크섬, diff·patch, split 한 줄씩', '파일을 묶고 줄이고 검증하는 기본기를 한 개념씩 반복합니다. gzip 이 원본을 .gz 로 바꾸는 것과 -k·-c·gunzip, zcat·zgrep, gzip 의 오류와 -r·-t, tar 의 목록 보기·-C·한 파일만 풀기·--strip-components, --exclude, 절대 경로 안내와 -P, -a 와 자동 인식, tar 와 파이프, 압축된 tar 는 갱신할 수 없는 것, zip 의 -r·-l·-d·-o·-t·-p, 해시 길이와 줄바꿈이 해시를 바꾸는 것, sha256sum -c 의 OK·FAILED 와 종료 코드, diff 의 형식과 종료 코드와 cmp, patch 의 --dry-run·-R·-b·.rej 와 디렉터리 패치(-p1), split 으로 나누고 cat 으로 합치기를 짧은 객관식·빈칸·순서 문제로 익히고, 내려받은 파일 검증하고 풀기, 패치로 만들어 적용하기, 큰 파일 나눠 옮기기, 제외 패턴으로 묶고 확인하기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (182, 'kubectl 로그와 디버깅 도구: logs 옵션, exec, cp, port-forward, events, debug', 'Pod 안을 들여다보는 kubectl 도구를 한 개념씩 반복합니다. logs 의 컨테이너 선택과 Defaulted container 안내, --tail·--limit-bytes·--since·--timestamps, --all-containers 와 --prefix, logs deploy/이름 과 라벨 셀렉터(-l)로 여러 Pod 보기와 Pod 당 기본 10줄, -f 와 --previous 가 실패할 때, exec 의 -- 표기와 종료 코드 전달·-i·-c, cp 의 업로드·다운로드 방향과 오류, port-forward 의 대상 형식과 실패, events 의 --sort-by·--field-selector·-A·--watch, kubectl debug 의 임시 컨테이너와 --target·--copy-to 를 짧은 객관식·빈칸·순서 문제로 익히고, 재시작하는 Pod 의 원인 로그 보기, 여러 Pod 의 로그 한꺼번에 보기, Pod 와 파일 주고받기, port-forward 로 Pod 서비스 확인하기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (183, '이미지 관리와 로그: untag·삭제, 필터, export·import, prune, system df, 로그 로테이션', '이미지와 컨테이너를 관리하고 정리하는 방법을 한 개념씩 반복합니다. 태그가 이름표라는 것과 Untagged·Deleted 의 차이, 마지막 태그와 ID 로 삭제할 때의 충돌, 컨테이너가 쓰는 이미지를 지울 때의 거부, images 의 reference·label 필터와 -q·--no-trunc, image inspect, export 와 import(CMD 가 비는 것과 --change, 레이어가 하나로 합쳐지는 것), prune 의 범위와 label 필터, system df, 기본 hostname 과 --hostname·--add-host, json-file 로그 로테이션과 --log-driver none, --shm-size 와 --ulimit, docker events 를 짧은 객관식·빈칸·순서 문제로 익히고, 라벨로 범위를 좁혀 이미지 정리하기, 컨테이너의 파일 시스템을 이미지로 옮기기, rmi 가 거부될 때 풀기, 로그가 커지지 않게 로테이션 설정하기의 순서를 연습합니다.', 'quiz', '도커'),
  (184, '병합 전략과 충돌 도구: --ff-only, -X·-s, --ours·--theirs, rerere, 추적 브랜치', '병합과 충돌을 다루는 도구와 원격 추적을 한 개념씩 반복합니다. merge --ff-only 와 --no-ff, 충돌 때의 CONFLICT 메시지와 UU 상태와 마커, 충돌 파일 목록과 ls-files -u 의 단계 번호, 병합에서의 --ours·--theirs 와 rebase 에서의 반대 방향, --continue·--abort 와 충돌 중 commit 오류, -X ours·theirs 와 -s ours 의 차이, merge.conflictstyle 의 diff3, rerere 의 기록과 재사용, status -sb 의 ahead·behind 와 git cherry, pull --ff-only 와 pull.ff, branch -u 와 push -u 와 @{u}, ls-remote 와 remote show 를 짧은 객관식·빈칸·순서 문제로 익히고, 충돌 해결하고 병합 마치기, 한쪽 버전으로 충돌 정리하기, 갈라진 브랜치 정리하고 push 하기, rerere 로 반복 충돌 줄이기의 순서를 연습합니다.', 'quiz', 'Git'),
  (185, 'grep 과 정규식 심화: BRE·ERE, -o, -P, 앵커·클래스, 역참조, -F, 종료 코드 한 줄씩', 'grep 과 정규식의 기본기를 한 개념씩 반복합니다. grep 의 종료 코드 0·1·2 와 -q·-s, 기본 정규식과 확장 정규식(-E)에서 + 와 | 와 {n,m} 이 다르게 해석되는 것, -o 로 일치한 부분만 뽑기와 -c 가 줄 수를 세는 것, 탐욕적 매칭과 [^>]*, -P 의 숫자 약식 표기와 미리보기, 앵커와 -x, POSIX 문자 클래스, 점과 -F 고정 문자열, 역참조, -e 와 -f 로 여러 패턴 주기와 대시로 시작하는 패턴, -m·-n·-b, 재귀 검색의 --include·--exclude·--exclude-dir·-l·-L 과 -r 과 -R 의 차이, 이진 파일 메시지와 -a, ps 와 grep 으로 찾을 때 grep 자신이 걸리는 문제를 짧은 객관식·빈칸·순서 문제로 익히고, 설정 파일에서 주석과 빈 줄 빼기, 숫자만 뽑고 세기, 폴더에서 파일 종류를 정해 검색하기, ps 결과에서 grep 자신 빼기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (186, 'Service 와 Endpoints 심화: 셀렉터·targetPort, EndpointSlice, 헤드리스, ExternalName, DNS', 'Service 가 Pod 로 연결되는 과정을 한 개념씩 반복합니다. Endpoints 와 EndpointSlice 읽기와 Endpoints 의 deprecated 경고, describe svc 의 Selector·Port·TargetPort·Endpoints 와 3개까지만 보이는 목록, 셀렉터 오타로 엔드포인트가 비는 것, targetPort 가 틀리거나 이름으로 쓸 때, 포트가 둘 이상일 때 필요한 이름과 NodePort 범위 오류, readinessProbe 와 notReadyAddresses, sessionAffinity: ClientIP, 서비스 환경 변수가 생기는 시점, Service DNS 이름 형태와 다른 네임스페이스에서의 접속과 resolv.conf, 헤드리스 Service 의 조회 결과와 포트 변환이 없는 것, ExternalName, 셀렉터 없는 Service 에 EndpointSlice 로 주소 연결하기, kubectl expose 를 짧은 객관식·빈칸·순서 문제로 익히고, 엔드포인트가 비어 있는 원인 찾기, targetPort 점검, 준비되지 않은 Pod 확인, 셀렉터 없는 Service 에 외부 주소 연결하기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (187, 'Dockerfile 지시어와 헬스체크·정지: HEALTHCHECK, STOPSIGNAL, ONBUILD, SHELL, VOLUME, ARG, WORKDIR', 'Dockerfile 지시어와 실행 옵션의 동작을 한 개념씩 반복합니다. HEALTHCHECK 의 starting·healthy·unhealthy 변화와 inspect 에 저장되는 모양, unhealthy 여도 컨테이너가 계속 실행되는 것, FailingStreak 과 Log, --start-period, --no-healthcheck 와 HEALTHCHECK NONE, docker run 의 --health-* 와 상태 필터, STOPSIGNAL 과 --stop-signal, --stop-timeout 과 종료 코드 137, ONBUILD 가 자식 빌드에서만 실행되는 것, SHELL 로 RUN 의 쉘을 바꾸고 -e 로 중간 실패를 잡는 것, VOLUME 지시어와 익명 볼륨, FROM 앞의 ARG 의 범위, WORKDIR 의 상대 경로와 -w, COPY 의 --chown·--chmod 를 짧은 객관식·빈칸·순서 문제로 익히고, 헬스체크 상태 변화 확인하기, 정상 종료 신호 맞추기, ONBUILD 베이스 이미지 만들고 쓰기, 빌드 중 실패를 놓치지 않게 하기의 순서를 연습합니다.', 'quiz', '도커'),
  (188, 'git config 다루기: 범위·우선순위, --show-origin, 별칭, include·includeIf, insteadOf', 'git config 의 동작을 한 개념씩 반복합니다. --show-origin 과 --show-scope 로 값의 출처 보기, 전역과 저장소 설정의 우선순위, 없는 키의 종료 코드와 --default, 값이 여러 개일 때의 오류와 --add·--replace-all·--unset-all, --type 으로 bool 과 int 해석, -c 로 한 번만 쓰는 설정, 별칭과 느낌표 셸 별칭과 기본 명령 이름 별칭의 무시, GIT_PAGER 환경 변수와 core.pager, include.path 의 상대 경로, includeIf 의 gitdir 와 onbranch, url.insteadOf 와 remote get-url, 섹션 이름 바꾸기와 지우기, 대소문자 규칙을 짧은 객관식·빈칸·순서 문제로 익히고, 설정이 어디서 왔는지 찾기, 프로젝트별 이메일 분리하기, 값이 여러 개일 때 하나로 정리하기, 별칭 만들고 쓰기의 순서를 연습합니다.', 'quiz', 'Git'),
  (189, '정렬과 열 다루기: sort -k·-n·-h·-u, uniq, cut, paste, join, comm, nl', '텍스트 줄과 열을 다루는 명령의 동작을 한 개념씩 반복합니다. sort 의 -n 숫자 정렬과 -r, -t·-k 필드 정렬과 -k2 와 -k2,2 의 차이, -u 중복 제거, -h 크기 정렬, -c 정렬 확인과 -o 로 같은 파일에 쓰기, uniq 가 이웃한 줄만 합치는 것과 -c·-d·-u, cut 의 -d·-f 필드 범위와 -s·--complement 와 -c·-b 위치 자르기, paste 의 -d·-s 와 짝이 안 맞을 때, join 의 키 합치기와 -a·-v·-o 와 정렬 오류, comm 의 세 열과 -12·-23·-13, nl 의 빈 줄 처리, basename 과 dirname 을 짧은 객관식·빈칸·순서 문제로 익히고, 빈도 순위 만들기, CSV 에서 열 뽑아 나이순 보기, 두 목록의 차이 구하기, 두 파일을 키로 합치기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (190, 'kubectl 컨텍스트·출력·삭제: config, --no-headers, 셀렉터, api-resources, explain, delete 옵션', 'kubectl 을 안전하게 쓰는 방법을 한 개념씩 반복합니다. config 의 current-context·get-contexts·use-context 와 set-context --namespace, --context 가 한 번만 적용되는 것, config view 의 DATA+OMITTED 와 --raw, --no-headers 와 custom-columns, jsonpath 에서 없는 필드와 맵 출력, 라벨 셀렉터의 in·notin·느낌표·쉼표, get all 의 범위와 -o name 모양, --field-selector 의 지원 필드, api-resources 의 --namespaced·--api-group 과 api-versions, explain 의 경로, delete 의 NotFound 와 --ignore-not-found, --cascade=orphan, --dry-run=client·server 를 짧은 객관식·빈칸·순서 문제로 익히고, 작업 네임스페이스로 바꿔 작업하기, 원하는 필드만 뽑아 쓰기, 라벨로 골라 안전하게 삭제하기, 리소스 종류에서 필드까지 찾기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (191, '실행 중 컨테이너 다루기: rename, update, 재시작 정책, --pids-limit, OOM, wait, top', '실행 중인 컨테이너를 다루는 명령의 동작을 한 개념씩 반복합니다. docker rename 의 오류와 호스트 이름 유지, docker update 로 메모리·CPU·PID 한도와 재시작 정책을 재시작 없이 바꾸고 inspect 로 확인하는 것, 메모리 최소값 오류, on-failure:N 의 재시작 횟수, on-failure 와 no 와 always 의 정상 종료 처리, 직접 정지한 always·unless-stopped 컨테이너, 잘못된 재시도 횟수 오류, --pids-limit 과 can''t fork, --memory 한도와 OOMKilled·종료 코드 137, docker wait 의 종료 코드, docker top 의 열, -it 가 저장하는 Tty·OpenStdin, docker stats --no-stream, ps 의 --no-trunc 와 status 필터를 짧은 객관식·빈칸·순서 문제로 익히고, 재시작 정책 동작 확인하기, 실행 중 자원 한도 조정하기, OOM 으로 죽은 컨테이너 원인 찾기, 이름 바꿔서 정리하기의 순서를 연습합니다.', 'quiz', '도커'),
  (192, '검색과 패치: git grep, rev-parse, symbolic-ref, describe, format-patch, apply, am', 'Git 으로 찾고 주고받는 명령의 동작을 한 개념씩 반복합니다. git grep 의 추적 파일 범위와 --untracked, -n·-c·-l·-L·-h 출력 형태, 옛 커밋에서 검색할 때의 앞 표기, --or·--and 조합, 종료 코드와 -q, rev-parse 의 --show-toplevel·--show-prefix·--abbrev-ref·--short 와 --verify 오류, symbolic-ref 와 분리된 HEAD, log 의 --graph·--first-parent·--merges, describe 의 태그-개수-해시 형태와 --abbrev=0·--exact-match·--always, format-patch 의 파일 이름과 번호, apply 와 am 의 차이, --check 와 실패 오류, am 의 --abort 를 짧은 객관식·빈칸·순서 문제로 익히고, 패치 파일로 변경 주고받기, am 이 실패했을 때 정리하기, 이력에서 문자열 찾아 위치 확인하기, 저장소와 브랜치 정보 확인하기의 순서를 연습합니다.', 'quiz', 'Git'),
  (193, '파일 다루기 옵션: ls 정렬, stat, touch, cp·mv 덮어쓰기, ln, realpath, mktemp, 변수 치환', '파일과 폴더를 다루는 명령의 옵션을 한 개념씩 반복합니다. ls 의 -S·-t·-r 정렬과 -a·-A·-d·-R·-F, stat -c 서식, touch 의 -d·-t·-r·-c 와 내용 유지, mkdir -p, cp 의 -n·-i·-u·-p 와 폴더 복사의 -r 과 대상이 이미 있을 때의 동작, mv 의 -n·-b·-v 와 덮어쓰기, 하드 링크와 심볼릭 링크의 차이와 끊어진 링크, realpath 와 readlink -f, mktemp 의 파일·폴더·권한·템플릿 오류, 변수의 %·%%·#·## 치환을 짧은 객관식·빈칸·순서 문제로 익히고, 임시 폴더에서 안전하게 작업하기, 복사본의 시각 유지 확인하기, 링크 끊어짐 점검하기, 파일 이름에서 확장자 분리하기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (194, '롤아웃 제어와 설정 주입: pause·resume, set env, undo, 진행 기한, envFrom, Downward API, finalizer, replace', 'Deployment 롤아웃과 설정 주입의 동작을 한 개념씩 반복합니다. rollout pause 중의 변경이 롤아웃을 시작하지 않는 것과 resume 으로 한 번에 적용되는 것, pause·resume 오류, set env 가 롤아웃을 만드는 것과 이름 뒤 - 로 지우기, undo 가 리비전 번호를 새로 받는 것과 이전 기록이 없을 때의 오류, progressDeadlineSeconds 와 ProgressDeadlineExceeded, 기본 maxSurge·maxUnavailable, envFrom 과 env 의 우선순위와 prefix, fieldRef·resourceFieldRef 와 downwardAPI 볼륨, 없는 ConfigMap 참조와 optional, generateName 과 ownerReferences, finalizer 가 있는 삭제, replace 와 apply 의 차이, create·replace 오류를 짧은 객관식·빈칸·순서 문제로 익히고, 여러 변경을 한 번의 롤아웃으로, 실패한 롤아웃 복구하기, 환경 변수 주입 확인하기, 지워지지 않는 오브젝트 정리의 순서를 연습합니다.', 'quiz', 'k8s'),
  (195, 'docker run 옵션 모음: --network, --hostname, --volumes-from, --shm-size, --cpus, --user, --env-file', 'docker run 과 logs 의 옵션 동작을 한 개념씩 반복합니다. --network none 의 lo 만 있는 장치와 host 네트워크에서 무시되는 -p 와 없는 네트워크 오류, --hostname·--domainname 과 hostname -f, --dns-search·--dns-option 과 --add-host 형식 오류, --volumes-from 의 공유와 :ro, --shm-size 의 기본 64M, --cpus 의 cpu.max 와 --cpuset-cpus, --memory-reservation 과 한도보다 클 때의 오류, --user 의 UID·GID 형식과 없는 이름 오류와 --group-add, -w 가 없는 경로를 만드는 것, -e 에 값을 안 쓸 때의 호스트 값 전달, --env-file 의 주석·공백·덮어쓰기 규칙, docker logs 의 --tail·-t·--since 와 표준 출력·오류 분리, inspect --type 을 짧은 객관식·빈칸·순서 문제로 익히고, 데이터 컨테이너로 볼륨 공유하기, 환경 변수 파일로 실행하기, 네트워크가 없는 컨테이너 점검하기, 로그 줄여 읽기의 순서를 연습합니다.', 'quiz', '도커'),
  (196, '참조와 변경 목록: for-each-ref, show-ref, update-ref, --name-status, --follow, -S·-G, sparse-checkout', 'Git 참조와 변경 이력을 읽는 명령의 동작을 한 개념씩 반복합니다. for-each-ref 의 출력과 --format, 주석 태그와 가벼운 태그의 오브젝트 종류, --contains·--merged 와 버전 순서 정렬, show-ref 의 출력과 -d, --verify 의 전체 이름 규칙과 종료 코드, update-ref 로 브랜치 옮기기와 옛 값 검사, 체크아웃한 브랜치에 썼을 때의 상태, diff 의 --name-only·--name-status·--diff-filter·--no-renames, 이름이 바뀐 파일의 --follow 이력, 로그의 -S 와 -G 의 차이, commit 의 --allow-empty 와 --date·--author 의 작성·커밋 날짜 구분을 짧은 객관식·빈칸·순서 문제로 익히고, 백업 참조 만들어 실험하기, 이름 바꾼 파일 이력 추적하기, 문자열이 바뀐 커밋 찾기, 필요한 폴더만 체크아웃하기의 순서를 연습합니다.', 'quiz', 'Git'),
  (197, '쉘 스크립트 인자와 상태: "$@", shift, getopts, set -e·-u, pipefail, PIPESTATUS, [[ ]], 산술, read', '쉘 스크립트가 인자와 종료 상태를 다루는 동작을 한 개념씩 반복합니다. "$@" 와 "$*" 와 따옴표 없는 $@ 의 차이, shift, getopts 의 옵션 문자열과 OPTARG·OPTIND, 오류 처리와 앞에 붙이는 콜론, 옵션이 멈추는 곳과 --, set -e 가 멈추지 않는 경우, set -u 와 기본값, pipefail 과 PIPESTATUS 를 바로 읽어야 하는 이유, 파이프 안의 while 이 만든 서브쉘과 프로세스 치환, [ ] 와 [[ ]] 의 빈 변수 차이, 산술의 8진수와 10# 접두어, read 의 필드 나누기, mapfile -t, bash -n·-x 와 command -v 를 짧은 객관식·빈칸·순서 문제로 익히고, 옵션과 인자 처리하기, 스크립트 점검하기, 파이프 실패 잡기, 백그라운드 작업 기다리기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (198, 'Pod 스펙 필드 읽기: command·args, $(VAR), startupProbe, tolerations, hostAliases, 사이드카, --from-env-file', 'Pod 스펙의 필드가 실제로 만드는 동작을 한 개념씩 반복합니다. command 와 args 가 이미지의 ENTRYPOINT·CMD 를 바꾸는 방식, $(VAR) 치환과 $$ 이스케이프, kubectl run 의 -- 뒤 인자와 --command 와 --expose, securityContext 의 runAsUser·runAsGroup·fsGroup 과 runAsNonRoot, startupProbe 가 있는 동안 livenessProbe 가 미뤄지는 것과 실패했을 때의 이벤트, 자동으로 붙는 tolerationSeconds 300, hostAliases 와 /etc/hosts, shareProcessNamespace 와 PID 1, hostNetwork 의 Pod IP, restartPolicy: Always 인 init 컨테이너(사이드카), --from-env-file 과 --from-file 의 키, get --raw 의 healthz·readyz, kubectl version --client, generateName 과 create·apply 를 짧은 객관식·빈칸·순서 문제로 익히고, command·args 확인하기, 느리게 시작하는 앱에 startupProbe 달기, 클라이언트와 API 서버 상태 확인하기, 사이드카가 있는 Pod 확인하기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (199, '컨테이너에 붙기·찾기·만들기: exec -e/-w/-u/-d, attach, create/start, ps 필터, --cidfile, --pull, --network-alias', '실행 중인 컨테이너를 다루는 명령과 옵션의 동작을 한 개념씩 반복합니다. docker exec 의 -e·-w·-u 가 그 명령에만 적용되는 것과 없는 폴더·상대 경로·없는 사용자의 오류, -d 분리 실행, 종료 코드 전달과 정지된 컨테이너의 오류, docker attach 가 붙은 뒤의 출력만 보여 주고 컨테이너 종료 코드로 끝나는 것, create 와 start 와 start -a 의 차이, ps 의 status·exited 필터와 -q·-n·-l, --cidfile 에 적히는 전체 ID, --pull never 와 기본 missing, no-new-privileges 와 NoNewPrivs, --sysctl 이 허용되는 범위, 사용자 정의 네트워크의 --network-alias 와 기본 bridge 의 오류를 짧은 객관식·빈칸·순서 문제로 익히고, exec 로 컨테이너 안 살펴보기, 만들어 두고 실행해 보기, 이름 별칭으로 연결하기, 컨텍스트로 대상 바꾸기의 순서를 연습합니다.', 'quiz', '도커'),
  (200, 'Git 일상 명령 정리: commit -a, add -A, stash, restore, reset, tag, clone --depth, fetch, diff --exit-code', 'Git 일상 작업의 동작을 한 개념씩 반복합니다. commit -a 가 담는 변경과 새 파일, add . 와 -A 와 -u 의 범위 차이, stash 와 -u·-m·pop·apply, restore 와 --staged, reset 의 --soft·기본·--hard 와 reflog, 태그를 만들고 push 하고 지우는 법과 로컬·원격 태그의 차이, clone 의 --depth·-b·--single-branch, fetch 와 pull 의 차이와 --all·--prune, merge-base --is-ancestor 의 종료 코드, diff 의 --exit-code 와 --quiet, --stat·--numstat·--shortstat 의 차이, format 과 tformat 의 줄바꿈, 여러 --grep 의 OR 과 -i, -n·--skip·--reverse 의 적용 순서를 짧은 객관식·빈칸·순서 문제로 익히고, 브랜치가 이미 들어갔는지 확인하기, 변경량을 단계별로 보기, 급한 수정 전에 작업 치워 두기, 태그 만들고 올리고 지우기의 순서를 연습합니다.', 'quiz', 'Git'),
  (201, '배열과 xargs: 배열 인덱스·+=·unset, 연관 배열, here-string, mapfile -t, xargs -n/-I/-P, printf -v', 'bash 배열과 반복 실행 도구의 동작을 한 개념씩 반복합니다. 배열의 인덱스·개수·음수 인덱스, "${arr[@]}" 와 "${arr[*]}" 와 따옴표 없는 확장의 차이, += 로 추가할 때의 인덱스와 괄호 없는 += 의 함정, unset 후 남는 빈 인덱스, 배열과 문자열 자르기, declare -A 연관 배열과 선언 없이 쓸 때의 함정, -v 와 :- 로 키 확인, here-string 과 파이프 read 의 차이, mapfile -t 와 서브쉘 문제, xargs 의 -n·-I·-r 과 -P 병렬 실행·종료 코드 123, printf -v 와 형식 재사용, seq 의 -s·-w, declare -p·-i·-r 속성을 짧은 객관식·빈칸·순서 문제로 익히고, 배열 만들고 순회하기, 연관 배열로 값 찾기, 파일 줄을 배열로 읽기, xargs 로 명령 반복하기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (202, 'Kustomize 와 일회성 실행: apply -k, namePrefix, images, configMapGenerator 해시, run --rm -i', 'kubectl 에 내장된 Kustomize 와 일회성 실행의 동작을 한 개념씩 반복합니다. kubectl kustomize 는 출력만 하고 apply -k 는 적용하며 apply -f 는 kustomization.yaml 을 변환하지 않는 것, kustomization 파일이 없을 때의 오류, namePrefix·nameSuffix·namespace 와 참조 자동 수정, labels 와 includeSelectors, images 의 newName·newTag, replicas 와 patches(부분 수정·JSON 패치), configMapGenerator 의 이름 해시와 내용 변경 시 새 ConfigMap 과 롤링·옛 ConfigMap 이 남는 것, diff -k 의 종료 코드, delete -k, kubectl run --rm -i 가 출력 후 Pod 를 삭제하는 것과 -i 없이 쓰면 나는 오류와 종료 코드 전달, minReadySeconds 와 AVAILABLE 의 관계, base 와 overlay 구조를 짧은 객관식·빈칸·순서 문제로 익히고, kustomize 로 안전하게 적용하기, base 와 overlay 로 환경 나누기, 설정을 바꿔 롤링하기, 일회성 Pod 로 점검하기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (203, '컨테이너 복사·재시작·정리: docker cp, restart, kill, rm -f, diff, commit, history, rmi, prune', '컨테이너와 이미지를 다루는 기본 명령의 동작을 한 개념씩 반복합니다. docker cp 로 호스트와 컨테이너 사이 파일을 주고받는 방향과 이름:경로 표기, 정지된 컨테이너에서도 되는 것, 없는 폴더 오류와 폴더 통째 복사, docker version 과 info 의 차이, restart 가 같은 컨테이너를 다시 시작해 파일이 남는 것, kill 이 SIGKILL 로 바로 끝내 종료 코드 137 이 되는 것, 실행 중인 컨테이너의 rm 오류와 -f, 컨테이너 안 파일이 stop·start 에서는 남고 rm 후에는 사라지는 것, diff 의 A·C·D, commit 이 볼륨 파일을 담지 않는 것, history 의 레이어, 컨테이너가 쓰는 이미지의 rmi 충돌, container prune 이 정지된 컨테이너만 지우는 것을 짧은 객관식·빈칸·순서 문제로 익히고, 파일 넣고 꺼내기, 바뀐 파일을 이미지로 남기기, 쓰는 이미지 지우기, 재시작 뒤 파일 확인의 순서를 연습합니다.', 'quiz', '도커'),
  (204, '쉘 편의 기능과 작업 제어: echo -e, cat -n, tail -f, basename, pushd, jobs·kill %1, pkill, alias, history', '터미널에서 자주 쓰는 편의 명령과 작업 제어를 한 개념씩 반복합니다. echo -n 과 -e, cat -n 과 -b 의 빈 줄 처리와 tac, tail -n +2 와 -f 와 head -c, basename 과 dirname, rmdir 의 빈 폴더 조건, pushd·popd 스택, 백그라운드 작업의 jobs 와 kill %1, wait 가 돌려주는 종료 코드, pgrep·pkill 의 -f 와 종료 코드, 스크립트 안에서 alias 가 확장되지 않는 것, history 와 !! 와 !1, 한 명령에만 주는 환경 변수와 export 의 차이를 짧은 객관식·빈칸·순서 문제로 익히고, 백그라운드 작업 정리, 폴더 위치 쌓고 돌아오기, alias 만들고 해제하기, 로그 따라보기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (205, '네임스페이스·조회·권한 기본: -n·-A, get all 범위, -o name, -w, --sort-by, auth can-i, annotate, scale 0', '네임스페이스와 조회, 권한 확인의 기본 동작을 한 개념씩 반복합니다. 네임스페이스를 중복해 만들 때의 AlreadyExists 오류, -n 을 생략하면 기본 네임스페이스만 보는 것, -A 가 NAMESPACE 열을 붙여 모두 보여 주는 것, get all 에 ConfigMap 과 Secret 이 나오지 않는 것, -o name 의 종류/이름 형식, --sort-by 의 만든 시각 정렬, -w 로 변화를 계속 지켜보는 것, version 과 cluster-info 의 차이, auth can-i 의 yes·no 와 종료 코드, Role 만으로는 권한이 없고 RoleBinding 으로 연결해야 하는 것, annotate 의 --overwrite 와 키 뒤 - 삭제, replicas 0 으로 줄여도 Deployment 가 남는 것, Pod 를 지우면 새 Pod 가 만들어지는 것, 네임스페이스를 지우면 안의 리소스가 함께 사라지는 것을 짧은 객관식·빈칸·순서 문제로 익히고, 실습 네임스페이스 만들어 쓰고 지우기, 읽기 권한 열어 주기, Deployment 내렸다 되살리기, Pod 변화 지켜보기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (206, 'Compose 기본 명령과 필드: up -d, -p·-f, down -v, stop·start, build·pull, ports, restart, ADD 와 COPY', 'docker compose 의 기본 명령과 compose 파일 필드의 동작을 한 개념씩 반복합니다. 폴더 이름이 프로젝트 이름이 되어 컨테이너와 네트워크 이름이 정해지는 것, -p 로 프로젝트 이름을, -f 로 다른 파일을 지정하는 것, down 과 down -v 의 볼륨 차이, stop 과 start 가 컨테이너를 지우지 않는 것과 ps -a, restart 가 같은 컨테이너를 다시 시작하는 것, up -d 를 다시 실행할 때 바뀐 서비스만 다시 만드는 것, ports 의 호스트:컨테이너 순서, 서비스 이름으로 접근하는 것, 서비스별 restart 정책, build 와 pull 의 대상, Dockerfile 을 고친 뒤 up -d --build 가 필요한 것, ADD 가 tar 를 풀고 COPY 는 그대로 복사하는 것, network prune 이 쓰지 않는 네트워크만 지우는 것을 짧은 객관식·빈칸·순서 문제로 익히고, 올리고 내리기, Dockerfile 고치고 반영하기, 멈췄다 다시 시작하기, 볼륨 데이터 남기고 내렸다 올리기의 순서를 연습합니다.', 'quiz', '도커'),
  (207, '스크립트 기본기 2와 사용자·그룹: [ -f -d -z ], case, until, set -x, source, trap, base64, useradd, usermod -aG', '쉘 스크립트 기본기와 사용자·그룹 관리를 한 개념씩 반복합니다. [ ] 의 파일 검사 -f·-d·-s, 빈 문자열 검사 -z·-n, 숫자 비교 -gt 와 문자열 비교의 차이, 따옴표 없는 빈 변수의 오류, case 가 첫 일치만 실행하는 것과 | 패턴·기본 분기, until 반복, set -x 와 bash -x 로 따라가기, source 와 bash 실행의 차이, trap EXIT 로 정리하기와 신호 잡기, SIGKILL 은 잡을 수 없는 것, base64 인코딩과 echo -n, usermod -aG 와 -G 의 차이, 그룹 폴더의 setgid, userdel 과 -r 을 짧은 객관식·빈칸·순서 문제로 익히고, 인자 검사 스크립트 뼈대, 종료 때 임시 파일 정리, 그룹 만들고 사용자 넣기, 사용자와 그룹 정리의 순서를 연습합니다.', 'quiz', '리눅스'),
  (208, 'ConfigMap·Secret·볼륨 기본: --from-file, base64, stringData, envFrom, 마운트 갱신, subPath, immutable, PVC', '설정과 저장소를 Pod 에 연결하는 기본 동작을 한 개념씩 반복합니다. ConfigMap 을 --from-literal·--from-file·--from-env-file 로 만들 때의 키 이름, 이미 있는 이름으로 create 할 때의 오류, Secret 의 base64 저장과 describe 가 크기만 보여 주는 것, stringData 가 data 로 바뀌는 것, 환경 변수로 쓰는 configMapKeyRef 와 envFrom, 볼륨으로 마운트하면 키마다 파일이 생기는 것, 읽기 전용 볼륨과 defaultMode, 고친 뒤 환경 변수는 그대로이고 볼륨 파일만 시간이 지나 바뀌는 것, subPath 파일이 갱신되지 않는 것, immutable 의 거부, 없는 참조의 CreateContainerConfigError 와 FailedMount, optional, PVC 의 Pending 과 Bound 와 데이터 유지, emptyDir 의 수명을 짧은 객관식·빈칸·순서 문제로 익히고, ConfigMap 을 환경 변수로 쓰기, Secret 만들고 값 확인, 설정 파일 마운트, PVC 로 데이터 남기기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (209, '포트·네트워크·실행 옵션: -p 형식, -P 와 EXPOSE, 포트 충돌, network connect, ENTRYPOINT, USER, -e, volume rm', '컨테이너의 포트와 네트워크, 실행 옵션의 동작을 한 개념씩 반복합니다. -p 의 호스트:컨테이너 순서와 docker port 확인, 호스트 주소를 붙인 -p, 호스트 포트를 생략했을 때의 임의 배정, /udp 프로토콜, 같은 호스트 포트를 쓸 때의 port is already allocated 와 Created 상태, EXPOSE 가 호스트에 공개하지 않는 것, -P 가 EXPOSE 한 포트를 모두 공개하는 것, --expose 가 안내일 뿐인 것, --network none 의 lo 만 있는 모습, network connect·disconnect 와 active endpoints 오류, ENTRYPOINT 와 CMD 에 run 인자가 적용되는 방식, USER 와 -u 의 우선순위, -e 값 생략과 빈 값, 사용 중인 볼륨의 rm 오류와 자동 생성을 짧은 객관식·빈칸·순서 문제로 익히고, 포트 공개하고 확인, 실행 중 네트워크 추가·분리, ENTRYPOINT 동작 확인, 사용 중인 볼륨 정리의 순서를 연습합니다.', 'quiz', '도커'),
  (210, '내용 비교와 신호·시간: diff -r·-q·-u, cmp, cat -A, fold, tr -s, kill -l·-0, 종료 코드 128+n, timeout', '파일 내용을 비교하고 숨은 문자를 보고, 신호와 시간 제한을 다루는 기본 동작을 한 개념씩 반복합니다. diff 의 종료 코드 0·1·2 와 기본 출력의 1c1·<·> 읽기, -q 요약, -r 폴더 비교와 Only in, -u 통합 형식, 프로세스 치환 비교, cmp 의 처음 다른 위치와 -s, cat -A 의 ^I·$·^M 와 -s 빈 줄 압축, fold 의 -w 와 -s, tr 의 -s 와 -d, kill -l 로 신호 이름과 번호 바꾸기, kill -0 으로 생존 확인, 신호로 끝난 프로세스의 종료 코드 128 더하기 신호 번호, timeout 의 124 와 -s KILL 의 137 을 짧은 객관식·빈칸·순서 문제로 익히고, 두 파일 비교하기, 두 폴더 비교하기, 윈도식 줄바꿈 정리, 시간 제한과 종료 코드 확인의 순서를 연습합니다.', 'quiz', '리눅스'),
  (211, 'kubectl 도구 모음: cp, wait, replace·--force, apply 출력, diff, api-resources, edit, 강제 삭제, 라벨·선택자, config', 'kubectl 을 다루는 기본 동작을 한 개념씩 반복합니다. kubectl cp 의 방향과 tar 메시지, wait 의 성공 출력과 시간 초과 오류와 --for=delete, replace 가 없는 리소스에서 NotFound 가 되는 것과 --force 의 삭제 후 재생성, apply 의 created·unchanged·configured, diff 의 종료 코드 0·1, api-resources 의 SHORTNAMES 와 NAMESPACED, edit 의 취소와 저장, --grace-period=0 --force 의 경고, 라벨의 --overwrite 와 env- 삭제, 라벨 선택자의 쉼표와 !키, config 의 컨텍스트와 기본 네임스페이스를 짧은 객관식·빈칸·순서 문제로 익히고, 파일 주고받기, apply 전에 차이 확인, 라벨 붙이고 바꾸고 지우기, 컨텍스트와 네임스페이스 바꾸기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (212, '컨테이너 상태와 종료 코드: ps -q·--filter, 125·126·127, wait, rename, pause, stop·kill, logs, exec -w·-e, prune', '컨테이너 상태를 읽고 다루는 기본 동작을 한 개념씩 반복합니다. docker ps 의 -q 와 -aq, --filter 를 여러 번 쓸 때의 조건, 컨테이너 안 명령의 종료 코드와 STATUS 의 Exited, 종료 코드 125·126·127 의 뜻, wait 의 동작, rename 과 이름 충돌, pause 한 컨테이너의 Paused 상태와 exec 오류, stop 과 kill 의 종료 코드 137 과 0, logs 의 --tail 과 -t, exec 의 -w 와 -e, 이름 충돌과 --rm, system df 의 열, container prune 의 확인과 -f, -i 와 파이프 입력을 짧은 객관식·빈칸·순서 문제로 익히고, 종료 코드 확인하기, 멈추고 다시 이어서 실행, 로그 줄여 보기, 정지한 컨테이너 정리의 순서를 연습합니다.', 'quiz', '도커'),
  (213, '함수·산술·입력과 파일 다루기: 함수 인자·local, 산술, expr, read, type, export, ls -t·-S·-d, sort -k, cp -i·-n, nl', '셸 함수와 입력, 파일 다루기의 기본 동작을 한 개념씩 반복합니다. 함수의 인자와 return 이 만드는 종료 코드, local 변수와 전역 변수, 산술 계산의 몫·나머지·거듭제곱, expr 의 공백, read 가 단어를 나누는 방식과 -r, type 과 command -v, export 와 자식 프로세스, ls 의 -t·-S·-r 정렬과 -d, sort 의 -k 와 -n, cp 의 -i 와 -n, nl 과 cat -n 의 차이, readlink 와 realpath 를 짧은 객관식·빈칸·순서 문제로 익히고, 함수 정의하고 호출하기, 변수를 자식 프로세스에 넘기기, 두 파일을 키로 합치기, 빈 폴더 지우기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (214, '컨테이너 실행과 점검: command·args, workingDir, 프로브, logs -c, --cascade=orphan, set env·resources, 서비스 DNS', '컨테이너 실행 설정과 점검, 확인 도구의 기본 동작을 한 개념씩 반복합니다. command 와 args 가 ENTRYPOINT 와 CMD 를 덮어쓰는 것, workingDir, liveness 의 httpGet 실패와 재시작, readiness 의 tcpSocket 실패가 0/1 Running 과 ready false 로 보이는 것, exec probe 의 종료 코드, 컨테이너가 둘인 Pod 의 logs 와 -c, --all-containers, --prefix, 없는 컨테이너 이름의 오류, --cascade=orphan 으로 ReplicaSet 과 Pod 를 남기는 것, set env 와 set resources 가 롤아웃을 일으키는 것, Pod 에는 set env 가 거부되는 것, 다른 네임스페이스의 서비스 DNS 이름, get --raw 의 healthz 와 kubectl version 읽기를 짧은 객관식·빈칸·순서 문제로 익히고, 명령과 작업 폴더 정하기, 준비 점검 실패 읽기, 환경 변수를 바꾸고 롤아웃, liveness 실패 읽기의 순서를 연습합니다.', 'quiz', 'k8s'),
  (215, '조회와 출력 형식: inspect·--format, ps --format·-n·-l·-s, port, 필터 3종, --no-trunc, stats --no-stream', '컨테이너 정보를 원하는 모양으로 읽는 기본기를 한 개념씩 반복합니다. docker inspect 의 JSON 출력과 --format 템플릿, json 함수, docker ps 의 --format 과 table, 공개한 포트를 보여 주는 docker port, -n 과 -l 로 최근 컨테이너 고르기, -s 의 SIZE 열, --no-trunc 의 64자리 ID, docker run -d 가 출력하는 ID, ancestor·exited·name 필터의 뜻, docker container ls 가 ps 와 같다는 점, stats --no-stream 의 동작을 짧은 객관식·빈칸·순서 문제로 익히고, 상태 조회하기, ps 로 골라 보기, 공개한 포트 확인하기, ID 길이 확인하기의 순서를 연습합니다.', 'quiz', '도커'),
  (216, 'find 조건 모음: -maxdepth, -o 와 -print, -empty, -newer, -size 올림, -mtime, -exec ; 와 +, -print0, -prune', 'find 의 조건과 동작을 한 개념씩 반복합니다. -maxdepth 와 -mindepth 의 깊이, -o 와 -print 의 묶임, ! 로 조건 뒤집기, -empty 가 고르는 파일과 폴더, -newer 의 기준 파일, -size 가 k 단위로 올려서 비교하는 방식, -mtime 의 +n 과 -n, -exec 의 ; 와 + 의 차이, -print0 와 xargs -0, -prune 으로 폴더 건너뛰기, -name 이 이름 부분만 비교한다는 점, -iname, find 의 종료 코드를 짧은 객관식·빈칸·순서 문제로 익히고, 일반 파일 좁혀 찾기, 공백 이름 안전하게 처리, 명령 한 번에 모아 실행, 시간으로 고르기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (217, 'Deployment 와 ReplicaSet: 파드 이름, 소유 관계, 재생성, 직접 scale, 라벨 떼기, cascade, set image, restart, 이력', 'Deployment 가 ReplicaSet 을 거쳐 파드를 관리하는 방식을 한 개념씩 반복합니다. 파드 이름에 붙는 해시, get rs 의 열, create deployment 의 기본값, ownerReferences 로 이어지는 소유 관계, 파드나 ReplicaSet 을 지웠을 때의 재생성, ReplicaSet 을 직접 scale 했을 때 되돌아가는 동작, 파드의 라벨을 떼면 생기는 일, scale 0 의 결과, delete 와 --cascade=orphan 의 차이, set image 와 rollout restart 가 만드는 새 ReplicaSet, CHANGE-CAUSE 어노테이션, 셀렉터를 바꿀 수 없다는 점을 짧은 객관식·빈칸·순서 문제로 익히고, 파드가 되살아나는 과정, 새 이미지로 롤아웃, 이력과 변경 사유, 삭제 방식 비교의 순서를 연습합니다.', 'quiz', 'k8s'),
  (218, '이미지 목록과 빌드: images -q·--format·--filter, tag·rmi, build -q·-f·--build-arg·--target, image inspect', '이미지를 찾고 만들고 정리하는 기본 동작을 한 개념씩 반복합니다. docker images 의 -q 와 --no-trunc, --format 템플릿, 저장소 이름과 reference 필터, docker tag 가 이름만 더 붙이는 동작, 별칭을 rmi 로 지울 때의 Untagged 와 컨테이너가 쓰는 이미지의 conflict, docker image rm 이 rmi 와 같다는 점, build -q 의 출력, --build-arg 와 ARG 기본값, -f 와 빌드 컨텍스트, 멀티 스테이지의 --target, image inspect 의 --format 을 짧은 객관식·빈칸·순서 문제로 익히고, 빌드하고 실행하기, 별칭 이름 달고 떼기, 빌드 인자 바꿔 보기, 단계별로 끊어 빌드의 순서를 연습합니다.', 'quiz', '도커'),
  (219, '파일 크기와 앞뒤 읽기: head -c·-n -N, tail -n +N·-c, wc -l·-L·-w, du 와 ls 크기, truncate, dd, split -l', '파일의 앞뒤와 크기를 읽는 명령을 한 개념씩 반복합니다. head -c 와 -n -N, tail -n +N 과 -c, wc -l 이 줄바꿈 개수를 센다는 점, -L 과 -w, wc 파일 이름 유무와 total 줄, head 와 tail 의 기본 10줄, 여러 파일의 ==> 머리글과 -q, truncate 로 늘리고 줄이기, ls 크기와 du 크기의 차이를 짧은 객관식·빈칸·순서 문제로 익히고, du -s 와 -d, dd bs, split -l 도 빈칸으로 연습하며 앞뒤 줄 확인, 크기 늘리고 줄이기, 나눈 뒤 합치기, 겉보기와 실제 크기의 순서를 연습합니다.', 'quiz', '리눅스'),
  (220, 'Pod 종료와 재시작 정책: restartPolicy 3가지, CrashLoopBackOff, 종료 코드, logs --previous, Job 재시도, SIGTERM', '파드가 끝나거나 실패했을 때 어떻게 되는지를 한 개념씩 반복합니다. restartPolicy 의 Never·OnFailure·Always 가 정상 종료와 실패 종료에서 각각 어떻게 다른지, Completed 와 Error 와 CrashLoopBackOff 와 ImagePullBackOff 가 보이는 경우, Deployment 에 Always 만 쓸 수 있다는 점, 실행 중인 파드의 restartPolicy 를 바꿀 수 없다는 점, kubectl run --restart, Job 의 Never 가 새 파드를 만들고 backoffLimit 이 재시도 한도를 정한다는 점, 종료 코드 읽기, logs --previous, SIGTERM 처리와 종료 유예 시간을 짧은 객관식·빈칸·순서 문제로 익히고, Never 실패 확인, OnFailure 재시작 관찰, Job 재시도 확인, 종료 신호 처리 비교의 순서를 연습합니다.', 'quiz', 'k8s'),
  (221, 'Dockerfile 실행 설정: CMD·ENTRYPOINT 와 run 인자, --entrypoint, 셸·exec 형식, .dockerignore, COPY --chown', 'Dockerfile 이 컨테이너의 실행 방식을 정하는 방법을 한 개념씩 반복합니다. docker run 의 인자가 CMD 를 덮어쓴다는 점, ENTRYPOINT 와 CMD 를 함께 쓸 때의 결합, --entrypoint 가 CMD 를 쓰지 않게 한다는 점, 셸 형식과 exec 형식의 변수 처리와 저장 모양, 셸 형식 ENTRYPOINT 가 인자를 받지 않는다는 점, CMD 를 두 번 쓰면 마지막만 효력이 있다는 점, .dockerignore 와 ! 예외, COPY --chown, LABEL 과 label 필터, build --label, RUN 과 CMD 의 실행 시점을 짧은 객관식·빈칸·순서 문제로 익히고, CMD 덮어쓰기, ENTRYPOINT 와 CMD, .dockerignore, 셸 형식과 exec 형식 비교의 순서를 연습합니다.', 'quiz', '도커'),
  (222, 'printf 서식과 seq·shuf: %s·%d·%x·%.2f, 너비와 0 채우기, 서식 되풀이, %b, %%, seq -w·-s, shuf -n·-e·-r', '출력 서식과 숫자·무작위 도구를 한 개념씩 반복합니다. printf 가 줄바꿈을 넣지 않는다는 점, 인자가 많을 때 서식이 되풀이되고 모자라면 빈 문자열이나 0 으로 채워진다는 점, %5s 와 %-5s 의 정렬, %.3s 로 자르기, %05d, 앞에 0 이 붙은 수가 8진수로 읽힌다는 점, %d 에 소수를 주면 나는 오류, %b 와 %s 의 차이, %% 로 퍼센트 출력, seq 의 -w·-s 와 증가분·감소, 끝이 시작보다 작을 때, shuf -n 이 중복 없이 뽑는다는 점과 -e·-i·-r 을 짧은 객관식·빈칸·순서 문제로 익히고, 정렬 서식 확인, 번호 붙은 이름 만들기, shuf 로 섞기 확인, 서식 되풀이 확인의 순서를 연습합니다.', 'quiz', '리눅스'),
  (223, 'Pending 원인 읽기: nodeSelector·nodeName, 노드 라벨, Insufficient cpu, required·preferred, PVC', '파드가 Pending 에서 멈췄을 때 원인을 읽는 방법을 한 개념씩 반복합니다. nodeSelector 가 맞지 않을 때, requests 가 노드보다 클 때의 Insufficient cpu 와 memory, PodScheduled 조건의 Unschedulable, 없는 노드를 nodeName 으로 지정했을 때 스케줄러가 건드리지 않는다는 점, 노드 어피니티 required 와 preferred 의 차이, 노드에 라벨을 붙이면 Pending 파드가 바로 배치된다는 점과 라벨을 떼도 실행 중인 파드는 남는다는 점, 없는 StorageClass 의 PVC, kubectl get 의 --field-selector 와 라벨 셀렉터의 차이, describe 의 Events, Pending 파드에 exec 가 안 되는 이유를 짧은 객관식·빈칸·순서 문제로 익히고, Pending 원인 찾기, 라벨로 풀기, 자원 부족 확인, required 와 preferred 비교의 순서를 연습합니다.', 'quiz', 'k8s'),
  (224, 'kubectl 출력에서 원하는 값만 뽑기: jsonpath, range, 필터, custom-columns, sort-by', 'kubectl get -o json 이 주는 JSON 의 구조를 읽고 원하는 값만 뽑는 연습입니다. 경로 읽기, range 로 한 줄씩, 이름과 이미지 함께, 점이 든 키, 조건 필터, custom-columns 표, sort-by 정렬, Secret base64 풀기를 차례로 익힙니다.', 'k8s', 'k8s'),
  (225, '도커 출력에서 원하는 값만 뽑기: inspect -f, range, index, ps --format·--filter', 'docker inspect 가 주는 JSON 의 구조를 읽고 -f 템플릿으로 값 하나만 뽑는 연습입니다. 상태·이미지·IP·종료 코드, range 로 환경 변수 한 줄씩, index 로 레이블 값, ps --format 표와 --filter 로 종료된 컨테이너만 고르기를 실습합니다.', 'docker', '도커'),
  (228, '도커 볼륨과 네트워크 실습: 데이터 보존, 바인드 마운트, 읽기 전용, 이름으로 통신', '볼륨을 만들고 컨테이너를 지워도 데이터가 남는지 확인하고, 바인드 마운트와 읽기 전용(:ro) 마운트를 비교합니다. 직접 만든 네트워크에서 컨테이너를 이름으로 부르고, 쓰는 중인 볼륨이 삭제되지 않는 이유를 찾아 정리하는 연습입니다.', 'docker', '도커'),
  (226, '디스크 사용량 점검 손에 익히기: df, du, sort -h, ls -lhS, find -size', '디스크가 찼다는 알람을 받았을 때 하는 일을 순서대로 연습합니다. df -h/-i 로 어느 디스크인지 보고, du -sh·--max-depth 로 큰 폴더를 좁히고, sort -h·ls -lhS·find -size 로 큰 파일을 찾고, 지우기 전후 크기를 비교합니다. df 와 du 가 어긋나는 이유도 짚습니다.', 'linux', '리눅스'),
  (227, 'Service 가 연결 안 될 때 원인 좁히기: Endpoints, selector 와 라벨, targetPort, readiness', 'Service 에 접속이 안 될 때 Endpoints 를 보고 원인을 좁혀 직접 고치는 연습입니다. get endpoints 와 describe svc 읽기, Pod 라벨 비교, kubectl label 과 patch 로 고치기, 두 라벨 조건, Ready 가 아닌 Pod, 틀린 targetPort, 겹친 원인까지 차례로 익힙니다.', 'k8s', 'k8s'),
  (231, '도커 컨테이너 들여다보기 실습: 로그, 프로세스, 자원, 파일 복사, 변경 내역', '실행 중인 컨테이너의 로그를 줄 수·시각으로 골라 보고, 프로세스·자원 사용량을 밖에서 확인합니다. 안에서 명령을 한 번 실행하고, 파일을 꺼내고 넣고, 바뀐 파일 목록과 재시작 횟수로 이상 징후를 읽는 연습입니다.', 'docker', '도커'),
  (230, 'Deployment 롤아웃과 복구: 이미지 업데이트, 이력 읽기, 잘못된 이미지 되돌리기, 재시작', 'Deployment 를 만들고 키우고 이미지를 바꾸는 롤링 업데이트부터, rollout history 읽기, 잘못된 이미지 태그(ImagePullBackOff) 알아채기, rollout undo 와 --to-revision 으로 되돌리기, CHANGE-CAUSE 적기, rollout restart 까지 직접 해 보며 익힙니다.', 'k8s', 'k8s'),
  (229, '프로세스 찾고 멈추기 손에 익히기: ps, pgrep, ss -ltnp, kill, pkill', '서버에서 프로세스를 다루는 일을 순서대로 연습합니다. ps -ef·ps -o·ps --sort 로 목록을 보고, pgrep 으로 PID 를 찾고, ss -ltnp 로 포트를 쥔 프로세스를 확인하고, & 와 $! 로 백그라운드 작업의 PID 를 기록한 뒤, kill·kill -9·pkill 로 종료합니다.', 'linux', '리눅스'),
  (233, 'Job 과 CronJob 실습: 만들기, 로그 읽기, 실패 고치기, 병렬 실행, 정해진 때 실행과 멈추기', 'Job 을 만들어 get jobs 의 COMPLETIONS 와 logs job/이름 을 읽고, 실패한 Job 을 고쳐 다시 만들고, completions 와 parallelism 으로 여러 번 실행해 보고, CronJob 을 만들어 create job --from 으로 지금 한 번 실행하고 patch 로 멈추는 것까지 직접 해 보며 익힙니다.', 'k8s', 'k8s'),
  (232, '사용자와 그룹 손에 익히기: id, useradd, usermod -aG, chown, chmod g+w, su -c', '리눅스 계정 관리를 순서대로 연습합니다. id 로 신원을 보고, /etc/passwd 를 cut·awk 로 읽고, useradd -m -s 로 계정을 만들고, usermod -aG 로 그룹에 더하고, chown·chmod g+w 로 파일 권한을 맞추고, su -c 로 다른 사용자 권한으로 실행한 뒤, userdel -r 로 정리합니다.', 'linux', '리눅스'),
  (234, '도커 이미지 손으로 만들기 실습: Dockerfile, build, tag, ENV·ARG, ENTRYPOINT, .dockerignore, history', '/tmp/app 에 Dockerfile 을 직접 쓰고 빌드해, 이미지가 실제로 만들어졌는지 실행 결과와 파일 내용으로 확인합니다. images 필터와 tag, ENV·ARG, ENTRYPOINT 와 실행 인자, COPY 와 .dockerignore, history 레이어 확인까지 한 단계씩 익힙니다.', 'docker', '도커'),
  (237, '도커 Compose 손으로 해 보기 실습: compose.yaml, up, ps, logs, exec, 환경 변수, 볼륨, -p, depends_on', '/tmp/stack 에 compose.yaml 을 직접 쓰고 alpine 서비스를 올려, 컨테이너 상태와 로그, 컨테이너 안 파일, 환경 변수로 결과를 확인합니다. ps --format, logs, exec, .env 변수 치환, 볼륨 데이터 유지, -p 프로젝트 이름, depends_on 까지 한 단계씩 익힙니다.', 'docker', '도커'),
  (235, '내 서버의 네트워크 직접 점검하기: ip, hostname, getent, /etc/hosts, ss, nc -z, curl', '인터넷 없이 서버 안에서 네트워크 상태를 점검하는 연습입니다. ip -br a 와 ip route 로 주소와 경로를 보고, hostname·getent hosts·/etc/resolv.conf 로 이름 풀이를 확인하고, nc 로 포트를 열고 ss -ltn 으로 확인하고, curl 의 HTTP 상태 코드와 종료 코드로 응답을 읽습니다.', 'linux', '리눅스'),
  (236, '설정 주입 실습: ConfigMap·Secret 만들기, 환경변수와 볼륨으로 주입, 설정 오류 진단, 값 바꾸고 반영하기', 'ConfigMap 을 from-literal 과 from-file 로, Secret 을 create secret generic 으로 만들고, 환경변수(valueFrom, set env --from)와 볼륨 마운트로 Pod 에 주입해 보고, 없는 ConfigMap 때문에 CreateContainerConfigError 가 난 Pod 를 진단해 고치고, 환경변수와 마운트 파일이 ConfigMap 변경에 다르게 반응하는 것을 rollout restart 로 반영하며 익힙니다.', 'k8s', 'k8s');
